// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"macitentan":{"wirkmechanismus":"Erweitert die Lungengefässe und bremst ihren krankhaften Umbau. Macitentan blockiert beide Endothelin-Rezeptoren (ETA und ETB) und hemmt so die gefässverengende, wachstums- und vernarbungsfördernde Wirkung von Endothelin-1. Es dringt gut ins Gewebe ein und bindet lange an die Rezeptoren; sein aktiver Metabolit Aprocitentan trägt zur Wirkung bei. In Studien verlangsamte Macitentan das Fortschreiten der Erkrankung.","nebenwirkungen":{"sehrHaeufig":["Nasen-Rachen-Entzündung (Erkältung)","Bronchitis","Anämie (Blutarmut)","Kopfschmerzen","Ödeme, Flüssigkeitsretention (Wassereinlagerungen)"],"haeufig":["Rachenentzündung, Grippe, Harnwegsinfekt","Hypotonie (tiefer Blutdruck)","Verstopfte Nase","Erhöhte Leberwerte (Transaminasen)","Leukopenie, Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Überempfindlichkeitsreaktionen (Schwellungen, Juckreiz, Ausschlag)"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Schwangerschaftstest vor Beginn und monatlich; zuverlässige Verhütung während und bis 1 Monat nach der Behandlung.","stillzeit":"Kontraindiziert – nicht stillen.","hinweise":["Frauen im gebärfähigen Alter: monatlicher Schwangerschaftstest und zuverlässige Verhütung bis 1 Monat nach Absetzen.","Hämoglobin und Leberwerte kontrollieren; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlich melden.","Rasche Gewichtszunahme oder Beinschwellungen melden."],"darreichung":["Filmtabletten"]},"macrogol":{"wirkmechanismus":"Hält Wasser im Darm zurück und macht so den Stuhl weicher und voluminöser, was die Darmbewegung anregt. Macrogol ist ein langkettiges, osmotisch wirksames Polymer, das Wassermoleküle über Wasserstoffbrücken bindet; es wird praktisch nicht aufgenommen und von den Darmbakterien nicht abgebaut. Die zugesetzten Elektrolyte sorgen dafür, dass der Körper netto kaum Wasser und Salze verliert. In den grossen Mengen der Darmspüllösungen (teils mit Natriumsulfat und Ascorbat) entsteht ein wässriger Durchfall, der den Dickdarm für Untersuchungen reinigt.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen und Blähbauch (v. a. bei Darmreinigung)","Übelkeit (v. a. bei Darmreinigung)","Beschwerden am After (v. a. bei Darmreinigung)"],"haeufig":["Durchfall, besonders bei zu hoher Dosis","Erbrechen","Darmgeräusche und Blähungen","Kopfschmerzen, Schwindel (bei Darmreinigung)","Durst, Frösteln, Unwohlsein (bei Darmreinigung)"],"gelegentlich":["Dyspepsie (Verdauungsbeschwerden)"],"unbekannt":["Allergische Reaktionen bis zur Anaphylaxie, Angioödem, Hautausschlag, Juckreiz","Elektrolytstörungen (Hyponatriämie, Hypo- oder Hyperkaliämie) und Dehydratation (Austrocknung)","Krampfanfälle bei schwerer Hyponatriämie (Natriummangel)","Herzrhythmusstörungen, Herzklopfen","Ischämische Kolitis (Durchblutungsstörung des Dickdarms), v. a. nach Darmreinigung"]},"schwangerschaft":"Macrogol wird kaum aufgenommen; zur Behandlung der Verstopfung kann es in der Schwangerschaft angewendet werden. Darmspüllösungen nur, wenn ärztlich notwendig.","stillzeit":"Keine Auswirkungen auf den gestillten Säugling zu erwarten; Anwendung möglich.","hinweise":["Pulver in der vorgeschriebenen Wassermenge auflösen und über den Tag ausreichend trinken.","Bei Darmreinigung andere Arzneimittel (z. B. Pille, Antiepileptika) mindestens 1 Stunde vor Beginn einnehmen, sonst werden sie ausgeschwemmt.","Bei Verstopfung, die ohne erkennbaren Grund länger als 2 Wochen anhält, ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Lösung zum Einnehmen (Beutel)"]},"magaldrat":{"wirkmechanismus":"Bindet überschüssige Magensäure und lindert Sodbrennen rasch. Magaldrat ist eine Aluminium-Magnesium-Verbindung mit Schichtgitterstruktur, die bei saurem pH-Wert schrittweise Hydroxidionen abgibt und so die Säure abpuffert, ohne den Mageninhalt stark alkalisch zu machen. Zusätzlich bindet es Gallensäuren und hemmt das Verdauungsenzym Pepsin. Nur geringe Mengen Aluminium und Magnesium werden ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"unbekannt":["Weiche Stühle, häufigerer Stuhlgang oder Durchfall, v. a. bei hohen Dosen","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Aluminium-Anreicherung bei Niereninsuffizienz mit Knochen- und Hirnschäden","Phosphatmangel (Hypophosphatämie) bei langer, hochdosierter Einnahme"]},"schwangerschaft":"Nur kurzfristig und in möglichst niedriger Dosis einnehmen, um die Aluminiumbelastung des Kindes gering zu halten.","stillzeit":"Kurzfristige Einnahme ist möglich; Aluminium und Magnesium gehen nur in geringen Mengen in die Muttermilch über.","hinweise":["Bei Bedarf etwa 1 Stunde nach den Mahlzeiten und vor dem Schlafengehen einnehmen; Kautabletten gut kauen, Gel vor Gebrauch durchkneten bzw. schütteln.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Suspension (Gel) zum Einnehmen","Kautabletten"]},"magnesium":{"wirkmechanismus":"Ersetzt Magnesium, das Muskeln und Nerven für eine normale Erregbarkeit brauchen. Magnesium ist Cofaktor von über 300 Enzymen, unter anderem aller ATP-abhängigen Reaktionen, und wirkt an Muskel- und Nervenzellen als natürlicher Gegenspieler von Calcium. Es stabilisiert die Zellmembranen und vermindert eine Übererregbarkeit, die bei Mangel zu Krämpfen, Muskelzuckungen und Herzrhythmusstörungen führen kann. Die Aufnahme aus dem Darm ist begrenzt; Überschüsse scheidet die gesunde Niere aus.","nebenwirkungen":{"unbekannt":["Weicher Stuhl oder Durchfall, vor allem bei hohen Dosen","Müdigkeit bei langdauernder hoch dosierter Einnahme","Injektion: Wärmegefühl, Hautrötung (Flush), Übelkeit, Blutdruckabfall, langsamer Puls","Hypermagnesiämie bei Niereninsuffizienz oder Überdosierung: Muskelschwäche, fehlende Reflexe, Atemschwäche, Herzrhythmusstörungen"]},"schwangerschaft":"Erlaubt; der Magnesiumbedarf ist in der Schwangerschaft erhöht.","stillzeit":"Erlaubt.","hinweise":["Abstand von 2–4 Stunden zu Tetracyclinen, Chinolonen, Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Bei Durchfall die Tagesmenge auf mehrere Einnahmen verteilen oder verringern.","Bei eingeschränkter Nierenfunktion nur nach ärztlicher Rücksprache einnehmen."],"darreichung":["Granulat","Brausetabletten","Kautabletten","Tabletten","Injektionslösung"]},"magnesiumsulfat":{"wirkmechanismus":"Ersetzt fehlendes Magnesium und dämpft die Erregbarkeit von Nerven und Muskeln. Magnesium wirkt als physiologischer Calcium-Gegenspieler: Es hemmt den Calciumeinstrom in die Zellen und an der motorischen Endplatte die Freisetzung von Acetylcholin, wodurch die Übertragung vom Nerv auf den Muskel abgeschwächt wird. Die krampfverhütende Wirkung bei Eklampsie beruht zusätzlich auf einer Hemmung von NMDA-Rezeptoren und einer Erweiterung der Hirngefässe. Am Herzen stabilisiert Magnesium die Zellmembran und verlangsamt die Erregungsleitung, was bei Torsade de pointes genutzt wird.","nebenwirkungen":{"unbekannt":["Wärmegefühl, Hautrötung (Flush) und Schwitzen während der Injektion","Übelkeit, Erbrechen, Durst","Kopfschmerzen, Schwindel, Schläfrigkeit","Blutdruckabfall (Hypotonie)","Bradykardie (verlangsamter Herzschlag) und Leitungsstörungen am Herzen","Abgeschwächte Muskelreflexe und Muskelschwäche (Zeichen eines zu hohen Magnesiumspiegels)","Atemdepression, Herzrhythmusstörungen bis Herzstillstand bei Überdosierung","Calciummangel (Hypokalzämie)","Schmerzen und Venenreizung an der Injektionsstelle"]},"schwangerschaft":"Mittel der Wahl zur Krampfvorbeugung bei Präeklampsie und Eklampsie. Eine Dauerbehandlung über mehr als 5–7 Tage soll vermieden werden (Calciummangel und Knochenveränderungen beim Ungeborenen); vor der Geburt gegebenes Magnesium kann beim Neugeborenen Atmung und Muskelspannung dämpfen.","stillzeit":"Magnesium geht in geringen Mengen in die Muttermilch über; Stillen ist erlaubt.","hinweise":["Wird nur unter ärztlicher Überwachung im Spital gegeben: Kontrolle von Kniesehnenreflex, Atemfrequenz, Urinausscheidung und Magnesiumspiegel.","Langsam injizieren bzw. infundieren; Calcium (z. B. Calciumgluconat) als Gegenmittel bereithalten.","Magnesiumsulfat zum Einnehmen (Bittersalz) wirkt abführend und ist nicht mit der Infusion gleichzusetzen."],"darreichung":["Injektionslösung","Infusionskonzentrat"]},"mannitol":{"wirkmechanismus":"Zieht Wasser aus den Geweben in die Blutbahn und erhöht die Urinmenge. Mannitol ist ein Zuckeralkohol, der kaum verstoffwechselt wird, die Blutgefässe kaum verlässt und in der Niere frei filtriert, aber nicht zurückgenommen wird. Im Blut erhöht es den osmotischen Druck und entzieht so bei intakter Blut-Hirn-Schranke Gehirn und Auge Flüssigkeit. Im Nierentubulus hält es Wasser zurück und bewirkt eine osmotische Diurese.","nebenwirkungen":{"unbekannt":["Störungen des Flüssigkeits- und Elektrolythaushalts (z. B. Hyponatriämie, Hyper- oder Hypokaliämie, Azidose)","Dehydratation (Austrocknung) oder Überwässerung mit Lungenödem und Herzinsuffizienz","Akutes Nierenversagen, besonders bei hohen Dosen","Kopfschmerzen, Schwindel, Krampfanfälle, verschwommenes Sehen","Übelkeit, Erbrechen, Durst, Mundtrockenheit","Blutdruckabfall oder -anstieg, Herzrasen, Brustschmerzen","Überempfindlichkeitsreaktionen bis Anaphylaxie","Venenentzündung; bei Paravasat Gewebeschäden bis Kompartmentsyndrom"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Mannitol in die Muttermilch übergeht; nur nach ärztlicher Abwägung anwenden.","hinweise":["Wird nur im Spital unter Kontrolle von Urinmenge, Nierenwerten, Elektrolyten und Flüssigkeitsbilanz verabreicht.","Konzentrierte Lösungen können bei Kälte auskristallisieren – vor Gebrauch durch Erwärmen auflösen und nur klare Lösung über einen Filter infundieren."],"darreichung":["Infusionslösung"]},"maprotilin":{"wirkmechanismus":"Hebt die Stimmung, indem es die Konzentration des Botenstoffs Noradrenalin im Gehirn erhöht. Maprotilin hemmt stark und recht selektiv die Wiederaufnahme von Noradrenalin, die von Serotonin kaum. Zusätzlich blockiert es deutlich Histamin-H1-Rezeptoren (dämpfend) und schwächer Muskarin- und Alpha-1-Rezeptoren. Die Halbwertszeit ist mit rund zwei Tagen lang; der Abbau erfolgt hauptsächlich über CYP2D6.","nebenwirkungen":{"haeufig":["Mundtrockenheit","Müdigkeit, Schläfrigkeit","Schwindel, Kopfschmerzen","Obstipation (Verstopfung)","Verschwommenes Sehen (Akkommodationsstörungen)","Zittern (Tremor), Muskelzuckungen","Hautausschlag","Gewichtszunahme"],"unbekannt":["Krampfanfälle","Blutdruckabfall beim Aufstehen, Herzrasen","Herzrhythmus- und Reizleitungsstörungen, QT-Verlängerung","Harnverhalt","Verwirrtheit, Unruhe, Umschlagen in eine Manie","Blutbildveränderungen bis Agranulozytose","Erhöhte Leberwerte, Hepatitis","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Anpassungs- und Entzugsstörungen (Atemprobleme, Zittern, Trinkschwäche, Krampfanfälle) möglich.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung, sonst abstillen.","hinweise":["Bei Krampfanfällen sofort ärztliche Hilfe holen; Dosis nie selbst erhöhen.","Die stimmungsaufhellende Wirkung setzt erst nach 2–3 Wochen ein; nicht abrupt absetzen.","Vorsicht beim Autofahren; keinen Alkohol trinken.","Eine Überdosis ist lebensgefährlich – für Kinder unzugänglich aufbewahren."],"darreichung":["Filmtabletten"]},"maralixibat":{"wirkmechanismus":"Lindert den Juckreiz, indem es die Menge an Gallensäuren im Körper senkt. Maralixibat hemmt im letzten Dünndarmabschnitt (Ileum) den Transporter IBAT (auch ASBT genannt), über den normalerweise der grösste Teil der Gallensäuren in den Körper zurückgeholt wird. Dadurch werden mehr Gallensäuren mit dem Stuhl ausgeschieden, und ihr Spiegel im Blut sinkt. Der Wirkstoff wird kaum ins Blut aufgenommen und wirkt fast nur im Darm.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Bauchschmerzen","Erbrechen"],"unbekannt":["Mangel an fettlöslichen Vitaminen (A, D, E, K)","Erhöhte Leberwerte","Magen-Darm-Blutungen","Knochenbrüche"]},"schwangerschaft":"Keine Erfahrungen; vorsichtshalber nicht anwenden, ausser nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Nur nach ärztlicher Abwägung; wegen der minimalen Aufnahme ins Blut ist ein Übergang in die Muttermilch kaum zu erwarten.","hinweise":["Vor einer Mahlzeit einnehmen und die Lösung mit der beiliegenden Dosierspritze genau abmessen.","Bei anhaltendem Durchfall oder Erbrechen ärztlichen Rat einholen; fettlösliche Vitamine und Leberwerte werden regelmässig kontrolliert."],"darreichung":["Lösung zum Einnehmen"]},"maraviroc":{"wirkmechanismus":"Verhindert, dass das HI-Virus in bestimmte Abwehrzellen eindringen kann. Maraviroc bindet selektiv an den menschlichen Chemokin-Rezeptor CCR5 auf der Oberfläche von CD4-Zellen. Dadurch kann das Virus-Hüllprotein gp120 nicht mehr an diesen Korezeptor andocken, und CCR5-trope HIV-1-Viren können nicht mit der Zelle verschmelzen. Gegen Viren, die den Korezeptor CXCR4 benutzen (CXCR4-trope oder dual/gemischt-trope Viren), wirkt Maraviroc nicht.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Appetitlosigkeit","Depression, Schlaflosigkeit","Schwindel, Kribbeln (Parästhesien), Geschmacksstörungen, Schläfrigkeit","Magen-Darm-Beschwerden (Übelkeit, Bauchschmerzen, Blähungen, Verstopfung, Verdauungsbeschwerden)","Hautausschlag","Erhöhte Leberwerte (Transaminasen)","Schwäche (Asthenie)"],"gelegentlich":["Krampfanfälle","Herzinfarkt, Durchblutungsstörung des Herzmuskels (Myokardischämie)","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Muskelentzündung (Myositis), erhöhte CK im Blut","Nierenversagen, Eiweiss im Urin","Erhöhtes Bilirubin"],"selten":["Angina pectoris (Brustenge)","Panzytopenie, Granulozytopenie (starke Verminderung von Blutzellen)","Toxische Hepatitis, Leberversagen","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Toxische epidermale Nekrolyse und andere schwere Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Erfahrungen beim Menschen sind begrenzt; Anwendung nur, wenn der Nutzen das mögliche Risiko überwiegt. Die HIV-Therapie in der Schwangerschaft legt eine spezialisierte Fachperson fest.","stillzeit":"Ob Maraviroc in die Muttermilch übergeht, ist nicht bekannt. Frauen mit HIV wird in der Regel vom Stillen abgeraten; das Vorgehen mit der behandelnden Fachperson besprechen.","hinweise":["Vor Beginn muss ein Tropismus-Test zeigen, dass nur CCR5-trope Viren vorliegen.","Kann Schwindel verursachen – Vorsicht beim Autofahren und beim raschen Aufstehen.","Bei Gelbsucht, dunklem Urin, Ausschlag oder Fieber sofort ärztliche Hilfe suchen (mögliche Leberschädigung).","Vor der Einnahme neuer Medikamente, auch pflanzlicher wie Johanniskraut, ärztlich oder in der Apotheke nachfragen."],"darreichung":["Filmtabletten"]},"maribavir":{"wirkmechanismus":"Hemmt die Vermehrung des Zytomegalievirus in den Körperzellen. Maribavir blockiert die virale Proteinkinase pUL97 kompetitiv an ihrer ATP-Bindungsstelle. Dadurch werden die Vermehrung der Virus-DNA, ihre Verpackung und das Ausschleusen neuer Viruspartikel aus dem Zellkern gestört. Anders als Ganciclovir muss Maribavir nicht durch pUL97 aktiviert werden und wirkt deshalb auch bei vielen Ganciclovir-resistenten Viren; umgekehrt hemmt es die Aktivierung von Ganciclovir und Valganciclovir.","nebenwirkungen":{"sehrHaeufig":["Geschmacksstörungen (Dysgeusie)","Übelkeit","Durchfall","Erbrechen","Müdigkeit"],"haeufig":["Kopfschmerzen","Oberbauchschmerzen","Appetitlosigkeit","Gewichtsabnahme","Erhöhte Blutspiegel von Immunsuppressiva"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. Anwendung in der Schwangerschaft und bei Frauen im gebärfähigen Alter ohne Verhütung nicht empfohlen.","stillzeit":"Nicht bekannt, ob Maribavir in die Muttermilch übergeht; ein Risiko für das Kind kann nicht ausgeschlossen werden. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Geschmacksstörungen sind sehr häufig und meist vorübergehend.","Während der Behandlung CMV-Viruslast und Spiegel der Immunsuppressiva regelmässig kontrollieren lassen.","Nicht gleichzeitig mit Ganciclovir oder Valganciclovir anwenden.","Kann mit oder ohne Mahlzeit eingenommen werden."],"darreichung":["Filmtabletten"]},"marstacimab":{"wirkmechanismus":"Hebt eine natürliche Bremse der Blutgerinnung auf, damit auch ohne Faktor VIII oder IX genügend Thrombin entsteht. Marstacimab ist ein humaner monoklonaler IgG1-Antikörper, der an die Kunitz-2-Domäne des Tissue Factor Pathway Inhibitors (TFPI) bindet und so dessen Hemmung von Faktor Xa aufhebt. Dadurch wird die Gerinnung über den Gewebefaktor-Weg verstärkt.","nebenwirkungen":{"haeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerzen)","Kopfschmerzen","Juckreiz"],"unbekannt":["Thromboembolische Ereignisse","Bluthochdruck","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine Erfahrungen; Anwendung nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung und einige Zeit danach zuverlässig verhüten.","stillzeit":"Unbekannt, ob Marstacimab in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird einmal wöchentlich unter die Haut gespritzt (Bauch oder Oberschenkel), nach Schulung auch selbst.","Bei Durchbruchblutungen Faktorpräparate nur in der niedrigsten wirksamen Dosis anwenden und das Vorgehen mit dem Hämophilie-Zentrum absprechen.","Zeichen einer Thrombose (Brustschmerz, Atemnot, Beinschwellung, Lähmungen) sofort ärztlich abklären lassen."],"darreichung":["Injektionslösung im Fertigpen oder in der Fertigspritze"]},"masern-mumps-roeteln-impfstoff":{"wirkmechanismus":"Löst eine stark abgeschwächte Infektion aus, nach der das Immunsystem dauerhaft vor Masern, Mumps und Röteln geschützt ist. Der Impfstoff enthält lebende, abgeschwächte Masern-, Mumps- und Rötelnviren, die sich nur begrenzt vermehren. Sie lösen eine Antikörper- und eine zelluläre Immunantwort aus. Nach zwei Dosen sind fast alle Geimpften langfristig vor Masern und Röteln geschützt; der Schutz vor Mumps ist etwas geringer.","nebenwirkungen":{"sehrHaeufig":["Rötung, Schmerzen und Schwellung an der Einstichstelle","Fieber (meist 5–12 Tage nach der Impfung)"],"haeufig":["Masernähnlicher Hautausschlag","Hohes Fieber über 39,5 °C","Bluterguss an der Einstichstelle"],"gelegentlich":["Lymphknotenschwellung","Schwellung der Ohrspeicheldrüse (Parotis)","Schnupfen, Husten","Durchfall, Erbrechen","Appetitlosigkeit, Unruhe, Schlafstörungen","Bindehautentzündung","Mittelohrentzündung"],"selten":["Fieberkrämpfe","Allergische Reaktionen"],"unbekannt":["Thrombozytopenie (Mangel an Blutplättchen) mit Blutungsneigung","Anaphylaxie (schwere allergische Reaktion)","Gelenkschmerzen und Gelenkentzündung (vor allem bei erwachsenen Frauen)","Hirnentzündung (Enzephalitis), aseptische Hirnhautentzündung, Guillain-Barré-Syndrom","Hoden- oder Nebenhodenentzündung","Gefässentzündungen (z. B. Purpura Schönlein-Henoch, Kawasaki-Syndrom)","Erythema multiforme (Hautreaktion)"]},"schwangerschaft":"Kontraindiziert. Eine Schwangerschaft soll bis 1 Monat nach der Impfung vermieden werden; eine versehentliche Impfung in der Schwangerschaft ist jedoch kein Grund für einen Abbruch.","stillzeit":"Impfung während der Stillzeit möglich, z. B. bei fehlendem Rötelnschutz nach der Geburt.","hinweise":["Zwei Dosen ergeben einen langdauernden Schutz; in der Schweiz mit 9 und 12 Monaten empfohlen, Nachholimpfung für alle nach 1963 Geborenen ohne zwei dokumentierte Dosen.","Fieber oder Hautausschlag 5–12 Tage nach der Impfung sind meist harmlos und nicht ansteckend.","Nach Kontakt mit Masern kann eine Impfung innerhalb von 72 Stunden die Erkrankung oft noch verhindern."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionssuspension"]},"masern-mumps-roeteln-varizellen-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen vier Viruserkrankungen zu bilden. Der Impfstoff enthält lebende, stark abgeschwächte Masern-, Mumps-, Röteln- und Varizella-Zoster-Viren (Oka-Stamm), die sich nach der Impfung nur begrenzt vermehren. Dadurch entstehen schützende Antikörper und eine zelluläre Immunantwort, ohne dass die Krankheiten ausbrechen. Für einen langfristigen Schutz sind zwei Dosen nötig.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Rötung an der Einstichstelle","Fieber über 38 °C (meist 5–12 Tage nach der Impfung)"],"haeufig":["Schwellung an der Einstichstelle","Hautausschlag","Reizbarkeit","Fieber über 39,5 °C"],"gelegentlich":["Infekte der oberen Atemwege","Lymphknotenschwellung","Durchfall, Erbrechen","Appetitlosigkeit","Schläfrigkeit, Schlaflosigkeit, Unruhe","Schwellung der Ohrspeicheldrüse (Parotis)"],"selten":["Fieberkrämpfe","Mittelohrentzündung","Husten"],"unbekannt":["Thrombozytopenie (Mangel an Blutplättchen) mit Blutungsneigung","Anaphylaxie (schwere allergische Reaktion)","Enzephalitis (Hirnentzündung), Kleinhirnentzündung, Guillain-Barré-Syndrom (sehr selten)","Aseptische Meningitis (Hirnhautentzündung)","Gürtelrose (Herpes zoster) durch das Impfvirus","Gelenkschmerzen, Gelenkentzündung","Kawasaki-Syndrom"]},"schwangerschaft":"Kontraindiziert. Nach der Impfung soll während 1 Monat eine Schwangerschaft vermieden werden; eine versehentliche Impfung ist aber kein Grund für einen Schwangerschaftsabbruch.","stillzeit":"Der Impfstoff ist für Kinder bestimmt; für stillende Frauen liegen keine ausreichenden Daten vor (Anwendung nur nach ärztlicher Abwägung).","hinweise":["Fieber und ein leichter Hautausschlag treten oft 5–12 Tage nach der Impfung auf.","Bei bläschenartigem Ausschlag nach der Impfung Kontakt zu Schwangeren, Neugeborenen und immungeschwächten Personen meiden.","Während 6 Wochen nach der Impfung keine Acetylsalicylsäure (Aspirin) geben.","Für vollständigen Schutz sind 2 Dosen nötig; Impfungen im Impfausweis eintragen lassen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionssuspension"]},"mavacamten":{"wirkmechanismus":"Vermindert die übermässige Pumpkraft des verdickten Herzmuskels und verringert so die Einengung des Ausflusstrakts der linken Herzkammer. Mavacamten hemmt selektiv und reversibel die ATPase des kardialen Myosins und reduziert die Zahl der Querbrücken zwischen Myosin und Aktin. Dadurch sinken die Hyperkontraktilität, der Druckgradient im linksventrikulären Ausflusstrakt und die Füllungsdrücke; Belastbarkeit und Beschwerden bessern sich.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Dyspnoe (Atemnot)"],"haeufig":["Synkope (Ohnmacht)","Systolische Dysfunktion (verminderte Pumpleistung, LVEF unter 50 %) bis hin zur Herzinsuffizienz"]},"schwangerschaft":"Kontraindiziert – im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter brauchen vor Beginn einen negativen Schwangerschaftstest und wirksame Verhütung bis 6 Monate nach der letzten Dosis.","stillzeit":"Nicht stillen – Übergang in die Muttermilch unbekannt.","hinweise":["Vor und während der Behandlung regelmässige Herzultraschall-Kontrollen (Echokardiografie) der Pumpfunktion.","Neue Medikamente – auch rezeptfreie wie Omeprazol oder Esomeprazol – nur nach Rücksprache mit der Ärztin oder dem Arzt beginnen oder absetzen.","Bei zunehmender Atemnot, Brustschmerzen, Herzklopfen, Beinschwellungen oder raschem Gewichtsanstieg sofort ärztliche Hilfe holen.","Patientenkarte immer mitführen."],"darreichung":["Hartkapseln"]},"mebendazol":{"wirkmechanismus":"Tötet Würmer im Darm ab, indem es ihren Zuckerstoffwechsel lahmlegt. Mebendazol bindet an das Tubulin der Wurmzellen und hemmt den Aufbau der Mikrotubuli; dadurch können die Darmzellen der Würmer keine Glukose mehr aufnehmen, ihre Energiereserven erschöpfen sich und die Parasiten sterben ab. Aus dem Darm wird nur ein kleiner Teil aufgenommen.","nebenwirkungen":{"haeufig":["Bauchschmerzen"],"gelegentlich":["Übelkeit, Erbrechen","Durchfall","Blähungen, Bauchbeschwerden"],"selten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Nesselsucht","Hautausschlag","Krampfanfälle (vor allem bei Säuglingen)","Schwindel","Hepatitis, erhöhte Leberwerte","Haarausfall","Neutropenie, Agranulozytose (vor allem bei hohen Dosen)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nicht anwenden (im Tierversuch fruchtschädigend); danach nur nach ärztlicher Abwägung.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Bei Madenwürmern alle Familienmitglieder gleichzeitig behandeln und die Behandlung nach 2–4 Wochen wiederholen.","Hygiene: Hände waschen, Fingernägel kurz halten, Unterwäsche, Bettwäsche und Handtücher bei mindestens 60 °C waschen.","Die Tabletten können gekaut oder geschluckt werden; Fasten oder ein Abführmittel ist nicht nötig."],"darreichung":["Tabletten"]},"mebeverin":{"wirkmechanismus":"Entspannt die verkrampfte Muskulatur des Magen-Darm-Trakts, ohne die normale Darmbewegung zu lähmen. Mebeverin wirkt direkt auf die glatte Muskulatur (muskulotrop): Es vermindert den Einstrom von Natrium- und Calciumionen in die Muskelzellen und senkt so deren Erregbarkeit und Kontraktionskraft. Im Gegensatz zu Butylscopolamin hat es praktisch keine anticholinergen Nebenwirkungen wie Mundtrockenheit oder Sehstörungen. Es wird rasch durch Esterasen zu unwirksamen Abbauprodukten gespalten.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen wie Nesselsucht (Urtikaria) oder Hautausschlag (Exanthem)","Angioödem und Gesichtsschwellung","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur wenige Erfahrungen; in der Schwangerschaft nicht empfohlen.","stillzeit":"Nicht ausreichend untersucht; in der Stillzeit nicht empfohlen.","hinweise":["Retardkapseln ganz mit Wasser schlucken, nicht öffnen oder kauen; in der Regel morgens und abends einnehmen."],"darreichung":["Retardkapseln"]},"mecasermin":{"wirkmechanismus":"Ersetzt den fehlenden Wachstumsfaktor IGF-1 und fördert so das Längenwachstum. Mecasermin ist gentechnisch hergestellter humaner Insulin-like Growth Factor 1, der normalerweise die wachstumsfördernde Wirkung des Wachstumshormons vermittelt. Beim primären IGF-1-Mangel bildet der Körper trotz ausreichend Wachstumshormon zu wenig IGF-1, etwa wegen eines Defekts des Wachstumshormon-Rezeptors. IGF-1 stimuliert die Knorpelzellen der Wachstumsfugen und wirkt zudem insulinähnlich blutzuckersenkend.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)","Kopfschmerzen","Lipohypertrophie (Fettgewebsverdickung) und Blutergüsse an der Einstichstelle"],"haeufig":["Krampfanfälle oder Bewusstlosigkeit durch Unterzuckerung","Vergrösserung von Mandeln und Rachenpolypen, Schnarchen, Schlafapnoe","Gutartige Hirndrucksteigerung","Hörminderung, Ohrenschmerzen, Flüssigkeit im Mittelohr","Erbrechen, Bauchschmerzen","Gelenk- und Gliederschmerzen, Skoliose","Thymusvergrösserung","Herzgeräusch, Herzrasen"],"gelegentlich":["Depression, Nervosität"],"unbekannt":["Gutartige und bösartige Tumoren","Überempfindlichkeitsreaktionen bis Anaphylaxie","Hüftkopfgleiten (Epiphysiolysis capitis femoris)"]},"schwangerschaft":"Keine Daten; Anwendung nicht empfohlen.","stillzeit":"Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Kurz vor oder nach einer Mahlzeit oder Zwischenmahlzeit unter die Haut spritzen; Einstichstellen wechseln.","Zeichen einer Unterzuckerung kennen; in den ersten Stunden nach der Injektion keine riskanten Aktivitäten.","Starke Kopfschmerzen, Sehstörungen, Hinken oder Hüftschmerzen ärztlich abklären lassen."],"darreichung":["Injektionslösung"]},"meclozin":{"wirkmechanismus":"Beugt Übelkeit und Erbrechen bei Reisekrankheit vor, indem es Signale aus dem Gleichgewichtsorgan zum Brechzentrum dämpft. Meclozin ist ein lang wirksamer H1-Rezeptor-Antagonist mit anticholinerger Wirkung; es hemmt die Erregungsübertragung im Gleichgewichtssystem und in der Chemorezeptor-Triggerzone des Hirnstamms. In Itinerol B6 ist es mit Pyridoxin (Vitamin B6) und in den Präparaten für Erwachsene und Schulkinder zusätzlich mit Coffein kombiniert, das der Müdigkeit entgegenwirkt.","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit","Mundtrockenheit","Kopfschmerzen","Sehstörungen (Akkommodationsstörungen)","Harnverhalt","Magen-Darm-Beschwerden","Unruhe, Herzklopfen oder Schlafstörungen (Coffein-Anteil)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nur nach ärztlicher Abwägung; ein Übergang in die Muttermilch ist möglich.","hinweise":["Zur Vorbeugung rechtzeitig vor Reiseantritt einnehmen.","Kann müde machen: Vorsicht beim Autofahren, keinen Alkohol trinken.","Für Kleinkinder gibt es eigene Zäpfchen; bei Kindern unter 6 Jahren nur auf ärztliche Verordnung."],"darreichung":["Kapseln","Zäpfchen (Suppositorien)"]},"medroxyprogesteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon Progesteron. In der hohen Dosis der Dreimonatsspritze hemmt Medroxyprogesteronacetat über die Hirnanhangdrüse die Ausschüttung von FSH und LH und unterdrückt so den Eisprung; zusätzlich verdickt sich der Schleim am Gebärmutterhals und die Gebärmutterschleimhaut bleibt dünn. In Tablettenform wandelt es die durch Östrogen aufgebaute Gebärmutterschleimhaut in die Sekretionsphase um und schützt sie so vor einer Überwucherung (Hyperplasie). Es hat zudem eine schwache glukokortikoidartige Wirkung.","nebenwirkungen":{"sehrHaeufig":["Gewichtszunahme oder -abnahme","Kopfschmerzen","Nervosität","Bauchschmerzen, Bauchbeschwerden","Unregelmässige Blutungen, Schmierblutungen oder Ausbleiben der Regel (Dreimonatsspritze)"],"haeufig":["Depression, verminderte Libido","Schwindel","Übelkeit, Blähbauch","Haarausfall, Akne, Hautausschlag","Rückenschmerzen","Brustschmerzen, Brustspannen","Scheidenausfluss, Scheidenentzündung","Wassereinlagerungen (Ödeme), Schwäche"],"gelegentlich":["Überempfindlichkeitsreaktionen","Schlaflosigkeit, Schläfrigkeit","Krampfanfälle","Hitzewallungen","Vermehrte Behaarung (Hirsutismus), Juckreiz","Absonderung aus der Brust (Galaktorrhö), Beckenschmerzen","Gelenkschmerzen, Muskelkrämpfe","Veränderte Leberwerte"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Anaphylaxie (schwere allergische Reaktion)","Osteoporose mit Knochenbrüchen","Gelbsucht","Bleibende Hauteinziehung oder Abszess an der Einstichstelle"],"unbekannt":["Verminderte Knochendichte bei längerer Anwendung","Lange anhaltendes Ausbleiben des Eisprungs nach dem Absetzen"]},"schwangerschaft":"Kontraindiziert. Vor jeder Spritze bzw. Behandlung eine Schwangerschaft ausschliessen.","stillzeit":"Die Dreimonatsspritze kann frühestens 6 Wochen nach der Geburt auch in der Stillzeit angewendet werden; geringe Mengen gehen in die Muttermilch über, ohne bekannte Schäden für das Kind.","hinweise":["Die Dreimonatsspritze alle 12 Wochen erneuern; liegt die letzte Spritze länger als 13 Wochen zurück, vor der nächsten eine Schwangerschaft ausschliessen.","Wegen möglicher Abnahme der Knochendichte auf ausreichend Calcium und Vitamin D, Bewegung und Rauchverzicht achten; die Anwendung regelmässig ärztlich überprüfen lassen.","Nach dem Absetzen kehrt die Fruchtbarkeit oft erst nach mehreren Monaten (häufig 6–12, teils länger) zurück.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Depot-Injektionssuspension (Dreimonatsspritze)","Tabletten"]},"mefenaminsaeure":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Mefenaminsäure gehört zu den Fenamaten und hemmt die Cyclooxygenasen COX-1 und COX-2. Sie wird in der Leber (vor allem über CYP2C9) abgebaut und über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit, Erbrechen, Bauchschmerzen","Dyspepsie (Verdauungsbeschwerden), Blähungen"],"unbekannt":["Schwindel, Kopfschmerzen, Schläfrigkeit","Hautausschlag, Nesselsucht, Asthmaanfälle, Anaphylaxie (schwere allergische Reaktion)","Magen-Darm-Geschwüre und -Blutungen, Kolitis","Hämolytische Anämie (Blutzerfall), Agranulozytose und andere Blutbildstörungen","Leberschäden, Gelbsucht","Nierenschäden bis Nierenversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Krampfanfälle bei Überdosierung"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich. Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Zu den Mahlzeiten einnehmen; bei Durchfall oder Hautausschlag das Mittel absetzen und ärztlichen Rat einholen.","Die verordnete Höchstdosis nicht überschreiten – eine Überdosierung kann Krampfanfälle auslösen.","So kurz wie möglich anwenden; Alkohol erhöht das Risiko für Magenblutungen.","Kann Schwindel und Schläfrigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Kapseln","Filmtabletten","Zäpfchen"]},"mefloquin":{"wirkmechanismus":"Tötet die Malaria-Erreger in den roten Blutkörperchen ab. Mefloquin wirkt gegen die Blutformen aller Plasmodienarten, nicht aber gegen die ruhenden Leberformen von P. vivax und P. ovale. Der genaue Mechanismus ist nicht vollständig geklärt; diskutiert werden eine Störung des Hämoglobinabbaus im Parasiten und eine Hemmung seiner Ribosomen. Mit einer Halbwertszeit von rund 2–3 Wochen bleibt Mefloquin lange im Körper.","nebenwirkungen":{"sehrHaeufig":["Abnorme Träume, Albträume","Schlaflosigkeit"],"haeufig":["Angst, Depression","Schwindel, Drehschwindel (Vertigo)","Kopfschmerzen","Sehstörungen","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Juckreiz"],"unbekannt":["Psychosen, Halluzinationen, Panikattacken, Verwirrtheit, Suizidgedanken","Krampfanfälle","Herzrhythmusstörungen, AV-Block, QT-Verlängerung","Lang anhaltende Gleichgewichtsstörungen und Ohrensausen (Tinnitus)","Periphere Neuropathie (Kribbeln, Taubheit)","Agranulozytose, aplastische Anämie","Stevens-Johnson-Syndrom","Leberschäden bis Leberversagen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, z. B. wenn eine Reise in ein Hochrisikogebiet unvermeidbar ist; die bisherigen Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Mit der Vorbeugung rechtzeitig vor der Abreise beginnen (um die Verträglichkeit zu prüfen) und bis 4 Wochen nach der Rückkehr fortsetzen.","Nach dem Essen mit reichlich Flüssigkeit einnehmen.","Bei Angst, Unruhe, Verwirrtheit, Niedergeschlagenheit, Albträumen oder Schwindel die Einnahme beenden und ärztlich ein anderes Mittel bestimmen lassen.","Schwindel und Sehstörungen können die Fahrtüchtigkeit beeinträchtigen, auch noch Wochen nach der letzten Dosis."],"darreichung":["Tabletten"]},"melatonin":{"wirkmechanismus":"Ersetzt das körpereigene Schlafhormon, dessen nächtliche Bildung im Alter und bei manchen Entwicklungsstörungen vermindert ist. Melatonin wird natürlicherweise nachts in der Zirbeldrüse gebildet und signalisiert dem Körper über die Melatoninrezeptoren MT1 und MT2, vor allem im Nucleus suprachiasmaticus (der «inneren Uhr»), dass es Nacht ist. Die Retardform gibt den Wirkstoff über mehrere Stunden ab und ahmt so die natürliche nächtliche Ausschüttung nach. Melatonin wird in der Leber hauptsächlich über CYP1A2 abgebaut.","nebenwirkungen":{"haeufig":["Bei Kindern und Jugendlichen (Slenyto): Schläfrigkeit, Müdigkeit, Kopfschmerzen, Stimmungsschwankungen, Reizbarkeit"],"gelegentlich":["Bei Erwachsenen: Kopfschmerzen, Migräne, Schwindel, Schläfrigkeit","Nervosität, Unruhe, Reizbarkeit, Schlaflosigkeit","Ungewöhnliche Träume, Albträume","Bauchschmerzen, Verdauungsbeschwerden, Übelkeit, Mundtrockenheit","Hautausschlag, Juckreiz, nächtliches Schwitzen","Erhöhter Blutdruck","Gewichtszunahme"],"selten":["Gürtelrose (Herpes zoster)","Stimmungsschwankungen, Aggressivität","Ohnmacht (Synkope), Gedächtnisstörungen","Sehstörungen, Tränenfluss","Herzklopfen, Angina pectoris (Brustenge)","Erhöhte Triglyceride (Blutfette)"],"unbekannt":["Angioödem und andere Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft vorsichtshalber nicht anwenden.","stillzeit":"Melatonin geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Retardtabletten unzerkaut schlucken (nicht zerkleinern oder zerkauen), sonst geht die verzögerte Freisetzung verloren.","Abends vor dem Schlafengehen einnehmen (Circadin 1–2 Stunden vorher und nach einer Mahlzeit).","Alkohol vermindert die Wirkung und sollte gemieden werden; Rauchen kann die Wirkung abschwächen.","Kann Schläfrigkeit verursachen – Vorsicht beim Autofahren und Bedienen von Maschinen."],"darreichung":["Retardtabletten"]},"meloxicam":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen in den Gelenken, indem es die Bildung entzündungsfördernder Botenstoffe hemmt. Meloxicam hemmt die Cyclooxygenasen und damit die Prostaglandinsynthese, wobei COX-2 bevorzugt gehemmt wird. Die lange Halbwertszeit von rund 20 Stunden erlaubt die Einnahme einmal täglich.","nebenwirkungen":{"sehrHaeufig":["Magen-Darm-Beschwerden wie Dyspepsie (Verdauungsbeschwerden), Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Blähungen, Durchfall"],"haeufig":["Kopfschmerzen"],"gelegentlich":["Anämie (Blutarmut)","Schwindel, Schläfrigkeit","Blutdruckanstieg, Hitzegefühl","Versteckte oder sichtbare Magen-Darm-Blutungen, Gastritis, Mundschleimhautentzündung","Erhöhte Leberwerte","Juckreiz, Hautausschlag, Angioödem (Schwellung von Haut und Schleimhaut)","Wassereinlagerungen, Hyperkaliämie (erhöhtes Kalium), veränderte Nierenwerte"],"selten":["Blutbildveränderungen","Stimmungsschwankungen, Albträume","Sehstörungen, Ohrensausen (Tinnitus)","Herzklopfen","Asthmaanfälle","Magen-Darm-Geschwüre, Kolitis, Speiseröhrenentzündung","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"sehrSelten":["Hepatitis","Magen-Darm-Durchbruch (Perforation)","Blasenbildende Hautreaktionen, Erythema multiforme","Akutes Nierenversagen"],"unbekannt":["Agranulozytose (Ausfall der weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Verwirrtheit","Herzinsuffizienz","Lichtempfindlichkeit der Haut"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich. Im letzten Drittel kontraindiziert.","stillzeit":"In der Stillzeit nicht empfohlen.","hinweise":["Einmal täglich mit Wasser zu einer Mahlzeit einnehmen; höchstens 15 mg pro Tag.","So niedrig dosiert und so kurz wie möglich – Herz-Kreislauf- und Magen-Darm-Risiko steigen mit Dosis und Dauer.","Alkohol erhöht das Risiko für Magenblutungen.","Kann Schwindel, Schläfrigkeit und Sehstörungen verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten"]},"melphalan":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihr Erbgut schädigt. Melphalan ist ein Phenylalanin-Abkömmling des Stickstofflosts und wird über Aminosäure-Transporter in die Zellen aufgenommen. Als bifunktionelles Alkylans vernetzt es die DNA-Stränge, sodass die Zellen ihre DNA nicht mehr verdoppeln können und absterben. In hoher Dosis zerstört es das Knochenmark weitgehend, weshalb danach eigene Stammzellen zurückgegeben werden.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Thrombozytopenie, Anämie","Übelkeit, Erbrechen","Durchfall und Mundschleimhautentzündung bei hoher Dosis (Infusion)"],"haeufig":["Haarausfall (bei hoher Dosis sehr häufig)","Vorübergehender Anstieg des Harnstoffs bei Myelom-Patienten mit Nierenschaden"],"selten":["Hämolytische Anämie (Blutzerfall)","Allergische Reaktionen bis zur Anaphylaxie (v. a. bei Infusion)","Interstitielle Lungenentzündung, Lungenfibrose","Leberschäden (erhöhte Leberwerte bis Gelbsucht)","Hautausschlag, Juckreiz"],"unbekannt":["Akute myeloische Leukämie, Myelodysplasie (Zweiterkrankungen)","Unfruchtbarkeit (fehlende Spermienbildung, Ausbleiben der Menstruation)","Venenthrombosen, Lungenembolie (v. a. in Kombination)","Lebervenenverschlusskrankheit nach Hochdosistherapie","Akutes Nierenversagen"]},"schwangerschaft":"Nicht anwenden: Melphalan kann das ungeborene Kind schädigen. Frauen und Männer müssen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – nicht stillen.","hinweise":["Tabletten ganz schlucken, nicht teilen; im Kühlschrank lagern.","Regelmässige Blutbildkontrollen; bei Fieber, Infekt- oder Blutungszeichen sofort ärztliche Hilfe holen.","Keine Lebendimpfungen während der Behandlung.","Vor Behandlungsbeginn Möglichkeiten zum Fruchtbarkeitserhalt besprechen."],"darreichung":["Filmtabletten","Pulver und Lösungsmittel zur Herstellung einer Injektions- bzw. Infusionslösung"]},"memantin":{"wirkmechanismus":"Schützt die Nervenzellen bei Alzheimer-Demenz vor einer krankhaften Dauerreizung durch den Botenstoff Glutamat. Memantin ist ein spannungsabhängiger, nicht kompetitiver NMDA-Rezeptor-Antagonist mit mittlerer Affinität: Es blockiert die Rezeptoren bei anhaltend erhöhtem Glutamatspiegel, lässt die normale, kurzzeitige Signalübertragung beim Lernen aber weitgehend zu. Es wird kaum verstoffwechselt und grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Überempfindlichkeitsreaktionen","Schläfrigkeit","Schwindel, Gleichgewichtsstörungen","Kopfschmerzen","Bluthochdruck","Atemnot (Dyspnoe)","Verstopfung","Erhöhte Leberwerte"],"gelegentlich":["Verwirrtheit, Halluzinationen","Gangstörungen","Herzinsuffizienz (Herzschwäche)","Venöse Thrombosen und Thromboembolien","Erbrechen","Müdigkeit","Pilzinfektionen"],"sehrSelten":["Krampfanfälle"],"unbekannt":["Psychotische Reaktionen","Depression, Suizidgedanken","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Nicht bekannt, ob Memantin in die Muttermilch übergeht; nicht stillen.","hinweise":["Einmal täglich, immer etwa zur gleichen Zeit, mit oder ohne Essen einnehmen; die Dosis wird wöchentlich gesteigert.","Eine starke Ernährungsumstellung (z. B. auf rein pflanzliche Kost) oder Natron-haltige Mittel können den Spiegel erhöhen – ärztlich besprechen.","Schwindel und Schläfrigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten","Tropflösung (Lösung zum Einnehmen)"]},"meningokokken-acwy-konjugatimpfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen Meningokokken der Gruppen A, C, W und Y zu bilden. Der Impfstoff enthält die Zuckerhülle (Kapselpolysaccharide) dieser Bakterien, die an ein Trägereiweiss (Diphtherie- bzw. Tetanus-Toxoid) gekoppelt ist. Durch diese Koppelung entsteht eine starke, T-Zell-abhängige Immunantwort mit Gedächtniszellen, auch bei Kleinkindern. Der Impfstoff enthält keine lebenden Bakterien.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Unwohlsein, Müdigkeit","Kleinkinder: Reizbarkeit, Schläfrigkeit, Appetitlosigkeit"],"haeufig":["Fieber","Schüttelfrost","Übelkeit, Erbrechen, Durchfall","Gelenkschmerzen","Hautausschlag"],"gelegentlich":["Schwindel","Juckreiz"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Ohnmacht (Synkope)","Krampfanfälle, auch Fieberkrämpfe","Ausgedehnte Schwellung des geimpften Arms oder Beins"]},"schwangerschaft":"Kann bei klarer Indikation (z. B. Reise, Ausbruch, Risikofaktor) nach ärztlicher Abwägung geimpft werden; es handelt sich um einen Totimpfstoff.","stillzeit":"Impfung in der Stillzeit möglich, wenn sie angezeigt ist.","hinweise":["Kann gleichzeitig mit anderen Impfungen gegeben werden (an verschiedenen Stellen).","Auffrischimpfungen und Impfschema gemäss Schweizerischem Impfplan bzw. Reisemedizin.","Nach der Impfung etwa 15 Minuten in der Praxis bleiben."],"darreichung":["Injektionslösung (Fertigspritze oder Durchstechflasche, intramuskulär)"]},"meningokokken-b-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen Meningokokken der Gruppe B zu bilden. Weil die Kapsel dieser Bakterien menschlichem Gewebe ähnelt, enthält der Impfstoff stattdessen drei gentechnisch hergestellte Oberflächenproteine (NHBA, NadA, fHbp) und Vesikel der äusseren Bakterienmembran (mit dem Protein PorA P1.4). Die gebildeten Antikörper töten Meningokokken mithilfe des Komplementsystems ab. Der Schutz hängt davon ab, ob der jeweilige Bakterienstamm diese Antigene trägt.","nebenwirkungen":{"sehrHaeufig":["Schmerz, Rötung, Schwellung und Verhärtung an der Einstichstelle","Fieber (vor allem bei Säuglingen)","Säuglinge und Kleinkinder: Reizbarkeit, Schläfrigkeit, ungewöhnliches Schreien, Essstörungen, Durchfall, Erbrechen","Jugendliche und Erwachsene: Kopfschmerzen, Übelkeit, Muskel- und Gelenkschmerzen, Unwohlsein"],"gelegentlich":["Krampfanfälle, auch Fieberkrämpfe","Fieber über 40 °C","Blässe","Ekzem"],"selten":["Kawasaki-Syndrom (Gefässentzündung bei Kleinkindern)","Nesselsucht"],"unbekannt":["Allergische Reaktionen bis Anaphylaxie","Hypoton-hyporesponsive Episode (schlaffer, kaum ansprechbarer Zustand)","Ausgedehnte Schwellung der geimpften Gliedmasse","Ohnmacht (Synkope)","Hautausschlag","Nackensteifigkeit und Lichtscheu (Meningismus)"]},"schwangerschaft":"Keine ausreichenden Daten. Nur bei klarem Ansteckungsrisiko nach ärztlicher Abwägung impfen.","stillzeit":"Keine ausreichenden Daten; Impfung nach ärztlicher Nutzen-Risiko-Abwägung.","hinweise":["Für einen vollständigen Schutz sind je nach Alter 2 bis 3 Dosen nötig; den Impfplan ärztlich festlegen.","Fieber nach der Impfung ist bei Säuglingen häufig; vorbeugendes Paracetamol nach ärztlicher Anweisung ist möglich.","Nach der Impfung etwa 15 Minuten sitzen bleiben (Ohnmachtsgefahr bei Jugendlichen)."],"darreichung":["Injektionssuspension in Fertigspritze (intramuskulär)"]},"meningokokken-c-konjugatimpfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen Meningokokken der Gruppe C zu bilden. Das Kapsel-Polysaccharid der Bakterien ist an ein Trägerprotein gekoppelt (bei NeisVac-C an Tetanus-Toxoid). Diese Kopplung aktiviert T-Helferzellen, sodass schon Säuglinge bakterientötende Antikörper und ein immunologisches Gedächtnis bilden. Der Impfstoff schützt nur gegen Serogruppe C und ersetzt die Tetanusimpfung nicht.","nebenwirkungen":{"sehrHaeufig":["Rötung, Schwellung und Schmerzen an der Einstichstelle","Reizbarkeit, Weinen, Schläfrigkeit und Appetitlosigkeit bei Säuglingen und Kleinkindern","Kopfschmerzen bei Jugendlichen und Erwachsenen"],"unbekannt":["Fieber","Erbrechen, Durchfall","Muskel- und Gelenkschmerzen","Krampfanfälle, auch Fieberkrämpfe","Hypoton-hyporesponsive Episode (schlaffer, kaum ansprechbarer Zustand) bei Säuglingen","Punktförmige Hautblutungen (Petechien, Purpura)","Rückfall eines nephrotischen Syndroms","Allergische Reaktionen bis Anaphylaxie"]},"schwangerschaft":"Keine ausreichenden Daten. Bei erhöhtem Ansteckungsrisiko kann nach ärztlicher Abwägung geimpft werden.","stillzeit":"Impfung nach ärztlicher Nutzen-Risiko-Abwägung möglich.","hinweise":["Gegen weitere Serogruppen (A, W, Y) schützt ein 4-fach-Konjugatimpfstoff – welcher Impfstoff passt, ärztlich klären.","Nach der Impfung etwa 15 Minuten sitzen bleiben (Ohnmachtsgefahr)."],"darreichung":["Injektionssuspension (intramuskulär)"]},"menotropin":{"wirkmechanismus":"Regt die Eierstöcke an, Eibläschen (Follikel) heranreifen zu lassen. Menotropin wird aus dem Urin von Frauen nach der Menopause gewonnen und enthält follikelstimulierendes Hormon (FSH) und LH-Aktivität im Verhältnis 1:1, wobei die LH-Aktivität teilweise von enthaltenem hCG stammt. FSH fördert Wachstum und Reifung der Follikel, LH unterstützt die Östrogenbildung im Follikel. Den Eisprung löst anschliessend eine hCG-Injektion aus.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähbauch, Übelkeit","Ovarielles Überstimulationssyndrom (OHSS)","Beckenschmerzen","Reaktionen an der Einstichstelle (Schmerzen, Entzündung)"],"gelegentlich":["Schwindel","Hitzewallungen","Erbrechen, Durchfall, Bauchbeschwerden","Eierstockzysten","Brustbeschwerden (Schmerzen, Spannen, Schwellung)","Müdigkeit"],"unbekannt":["Überempfindlichkeitsreaktionen","Thromboembolie","Stieldrehung eines Eierstocks (Ovarialtorsion)","Juckreiz, Nesselsucht"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Injektion unter die Haut nach Anleitung, möglichst täglich zur gleichen Zeit.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"mepivacain":{"wirkmechanismus":"Betäubt vorübergehend die Nerven im behandelten Gebiet, sodass keine Schmerzen weitergeleitet werden. Mepivacain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und verhindert so die Erregungsleitung. Im Gegensatz zu vielen anderen Lokalanästhetika erweitert es die Blutgefässe kaum und wirkt deshalb auch ohne Adrenalinzusatz ausreichend lange. Als Amid-Lokalanästhetikum wird es in der Leber abgebaut.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall)","Übelkeit"],"haeufig":["Parästhesien (Kribbeln, Taubheitsgefühl)","Schwindel","Bradykardie (langsamer Puls)","Bluthochdruck","Erbrechen"],"gelegentlich":["Zeichen einer Überdosierung: Taubheit von Zunge und Mund, Ohrensausen, Sehstörungen, Zittern, Krampfanfälle, Bewusstlosigkeit"],"selten":["Allergische Reaktionen bis anaphylaktischer Schock","Herzrhythmusstörungen, Herzstillstand","Nervenschäden (Neuropathie), Entzündung der Rückenmarkshäute nach rückenmarksnaher Gabe","Doppeltsehen","Atemdepression"]},"schwangerschaft":"Langjährige Erfahrung ohne Hinweise auf Fehlbildungen; Anwendung nach ärztlicher Abwägung möglich. In der Geburtshilfe wird Mepivacain kaum eingesetzt, weil Neugeborene es nur langsam abbauen.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; bei üblicher Dosierung kann weiter gestillt werden.","hinweise":["Nach einer Betäubung im Mund erst essen oder heiss trinken, wenn das Taubheitsgefühl abgeklungen ist (Gefahr von Biss- und Verbrennungsverletzungen), besonders bei Kindern.","Die Fahrtüchtigkeit kann nach dem Eingriff vorübergehend beeinträchtigt sein.","Allergien auf Lokalanästhetika, Herzkrankheiten und die Einnahme von Blutverdünnern vor der Behandlung angeben."],"darreichung":["Injektionslösung","Zylinderampullen für die Zahnmedizin (teils mit Adrenalin)"]},"mepolizumab":{"wirkmechanismus":"Vermindert die Zahl bestimmter Entzündungszellen (eosinophile Granulozyten) im Blut und im Gewebe. Mepolizumab bindet an den Botenstoff Interleukin-5 (IL-5) und verhindert dessen Bindung an den IL-5-Rezeptor der Eosinophilen. Da IL-5 für Bildung, Aktivierung und Überleben dieser Zellen entscheidend ist, geht die eosinophile Entzündung zurück – Asthmaanfälle werden seltener, und Kortisontabletten können oft reduziert werden.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Infekte der unteren Atemwege, Rachenentzündung (Pharyngitis), Harnwegsinfekt","Überempfindlichkeitsreaktionen (z. B. Ausschlag, Juckreiz, Schwellungen)","Verstopfte Nase","Oberbauchschmerzen","Ekzem","Rückenschmerzen","Fieber","Reaktionen an der Einstichstelle (Schmerz, Rötung, Schwellung) und andere anwendungsbedingte Reaktionen"],"selten":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Begrenzte Erfahrungen; Antikörper gehen über die Plazenta auf das Kind über. Vorzugsweise nicht anwenden, ausser der Nutzen für die Mutter überwiegt das mögliche Risiko für das Kind.","stillzeit":"Nicht bekannt, ob Mepolizumab in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird alle 4 Wochen unter die Haut gespritzt; nach Schulung ist die Selbstinjektion mit Fertigpen oder Fertigspritze möglich.","Im Kühlschrank lagern, nicht einfrieren.","Bei Atemnot, Ausschlag oder Schwellungen nach der Injektion sofort ärztliche Hilfe holen.","Asthma- und Kortisonmedikamente nicht eigenmächtig absetzen."],"darreichung":["Injektionslösung (Fertigpen, Fertigspritze)","Pulver zur Herstellung einer Injektionslösung"]},"mercaptamin-cysteamin":{"wirkmechanismus":"Vermindert die Ablagerung von Cystin, das bei Cystinose Nieren, Augen und andere Organe schädigt. Bei der Cystinose kann die Aminosäure Cystin wegen eines defekten Transporters (Cystinosin) die Lysosomen nicht verlassen und kristallisiert aus. Mercaptamin gelangt in die Lysosomen und spaltet Cystin in Cystein und ein gemischtes Disulfid aus Cystein und Mercaptamin, die über andere Transporter ausgeschleust werden. Die Augentropfen lösen die Kristalle in der Hornhaut, die mit der Einnahme nicht erreicht werden.","nebenwirkungen":{"sehrHaeufig":["Erbrechen, Übelkeit, Durchfall","Appetitlosigkeit","Lethargie (Antriebslosigkeit), Fieber","Augentropfen: Augenschmerzen, Augenreizung, vorübergehend verschwommenes Sehen, Ablagerungen an Wimpern und Lidrand"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Magen-Darm-Entzündung","Unangenehmer Mund- und Körpergeruch","Hautausschlag","Kopfschmerzen","Enzephalopathie (Hirnfunktionsstörung)","Erhöhte Leberwerte","Schwäche (Asthenie)"],"gelegentlich":["Leukopenie (Mangel an weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle, Schläfrigkeit, Nervosität, Halluzinationen","Magen-Darm-Geschwüre und -Blutungen","Dehnungsstreifen, brüchige Haut, Haarfarbveränderungen, Gefässwucherungen an den Ellenbogen","Überstreckbare Gelenke, Knochenschwäche (Osteopenie), Knochenbrüche, Skoliose","Nephrotisches Syndrom (Eiweissverlust über die Niere)"],"unbekannt":["Gutartige Hirndrucksteigerung (Pseudotumor cerebri) mit Schwellung der Sehnervenpapille"]},"schwangerschaft":"Im Tierversuch fruchtschädigend. Die Kapseln nur anwenden, wenn unbedingt nötig; bei geplanter oder eingetretener Schwangerschaft die Behandlung sofort ärztlich überprüfen lassen.","stillzeit":"Die Kapseln sind in der Stillzeit kontraindiziert. Augentropfen nur nach ärztlicher Abwägung.","hinweise":["Kapseln genau im verordneten Zeitabstand einnehmen, auch nachts; Procysbi nicht zusammen mit fettreichen Mahlzeiten einnehmen.","Schwefelartiger Mund- und Körpergeruch ist häufig und harmlos; gute Mundhygiene kann helfen.","Regelmässige Kontrollen: Cystin in den weissen Blutkörperchen, Blutbild, Leberwerte, Haut und Knochen.","Augentropfen: ungeöffnet im Kühlschrank lagern, nach Anbruch höchstens 7 Tage verwenden; Kontaktlinsen vor dem Eintropfen herausnehmen."],"darreichung":["Hartkapseln","Magensaftresistente Hartkapseln","Magensaftresistentes Granulat","Augentropfen"]},"mercaptopurin":{"wirkmechanismus":"Hemmt die Vermehrung rasch wachsender Zellen, insbesondere von Leukämiezellen. Mercaptopurin ist eine Vorstufe (Prodrug): In der Zelle wird es durch das Enzym HGPRT zu Thioinosinmonophosphat und weiter zu Thioguanin-Nukleotiden umgewandelt. Diese hemmen die Neubildung von Purin-Bausteinen und werden als falsche Bausteine in DNA und RNA eingebaut, was zum Zelltod führt. Abgebaut wird Mercaptopurin vor allem durch die Enzyme Thiopurin-Methyltransferase (TPMT) und Xanthinoxidase.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung mit Leukopenie (Mangel an weissen Blutkörperchen) und Thrombozytopenie (Mangel an Blutplättchen)"],"haeufig":["Anämie (Blutarmut)","Appetitlosigkeit","Übelkeit, Erbrechen","Leberschädigung mit Gallenstau (erhöhte Leberwerte, Gelbsucht)"],"gelegentlich":["Bakterielle und virale Infektionen","Überempfindlichkeitsreaktionen mit Gelenkschmerzen, Hautausschlag und Fieber","Leberzellnekrose (Absterben von Lebergewebe)"],"selten":["Geschwüre der Mundschleimhaut","Pankreatitis (Bauchspeicheldrüsenentzündung)","Haarausfall","Bösartige Neubildungen, z. B. Lymphome, Hautkrebs"],"sehrSelten":["Darmgeschwüre","Vorübergehend verminderte Spermienzahl","Sekundäre Leukämie und Myelodysplasie"],"unbekannt":["Venookklusive Lebererkrankung (Verschluss kleiner Lebervenen), Pfortaderhochdruck","Hepatosplenisches T-Zell-Lymphom (seltener, aggressiver Lymphdrüsenkrebs)","Lichtempfindlichkeit der Haut","Hypoglykämie (Unterzuckerung), v. a. bei Kindern"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit anwenden, da Mercaptopurin das Ungeborene schädigen kann. Frauen und Männer müssen während der Behandlung und einige Monate danach zuverlässig verhüten.","stillzeit":"Mercaptopurin geht in die Muttermilch über; während der Behandlung nicht stillen.","hinweise":["Regelmässige Kontrollen von Blutbild und Leberwerten sind nötig; Fieber, Halsschmerzen, blaue Flecken oder Blutungen sofort melden.","Täglich zur gleichen Zeit und immer gleich einnehmen (entweder mit oder ohne Essen), möglichst nicht zusammen mit Milch oder Milchprodukten.","Haut konsequent vor Sonne schützen (Kleidung, Sonnencreme).","Keine Lebendimpfungen ohne Rücksprache mit der Ärztin oder dem Arzt."],"darreichung":["Tabletten"]},"meropenem":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Meropenem bindet an die Penicillin-bindenden Proteine (PBP) der Bakterien und blockiert so die Quervernetzung des Zellwandbausteins Peptidoglykan; die Bakterien platzen. Als Carbapenem ist es gegen die meisten Betalaktamasen einschliesslich ESBL stabil und wirkt gegen viele grampositive, gramnegative (auch Pseudomonas) und anaerobe Erreger. Carbapenemase-bildende Bakterien und MRSA sind resistent.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Kopfschmerzen","Hautausschlag, Juckreiz","Erhöhte Leberwerte (Transaminasen, alkalische Phosphatase, LDH)","Thrombozytose (Vermehrung der Blutplättchen)","Entzündung und Schmerzen an der Einstichstelle"],"gelegentlich":["Pilzinfektionen in Mund oder Scheide (Candidose)","Veränderungen des Blutbilds (Eosinophilie, Thrombozytopenie, Leukopenie, Neutropenie)","Agranulozytose (starker Mangel an weissen Blutkörperchen) und hämolytische Anämie (Blutzerfall)","Parästhesien (Kribbeln)","Antibiotika-assoziierte Kolitis (Dickdarmentzündung)","Anaphylaxie und Angioödem (schwere allergische Reaktion, Schwellungen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Erhöhte Nierenwerte und erhöhtes Bilirubin"],"selten":["Krampfanfälle"],"unbekannt":["Delir (akute Verwirrtheit)","DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Akute generalisierte exanthematische Pustulose (AGEP)"]},"schwangerschaft":"Erfahrungen bei Schwangeren sind begrenzt; Tierversuche zeigen keine schädliche Wirkung. Anwendung nur, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über. Nur nach ärztlicher Abwägung anwenden; beim Säugling auf Durchfall und Pilzbefall achten.","hinweise":["Wird im Spital als Infusion oder Injektion verabreicht; die Dosis richtet sich nach Infektion und Nierenfunktion.","Unbedingt angeben, wenn Valproinsäure eingenommen wird oder eine Penicillin- bzw. Antibiotika-Allergie besteht.","Bei starkem oder anhaltendem Durchfall – auch Wochen nach der Behandlung – ärztliche Hilfe holen."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"mesalazin":{"wirkmechanismus":"Hemmt die Entzündung direkt an der Darmschleimhaut. Mesalazin (5-Aminosalicylsäure) vermindert die Bildung entzündungsfördernder Botenstoffe wie Prostaglandine und Leukotriene, fängt Sauerstoffradikale ab und dämpft entzündliche Signalwege (u. a. NF-κB, Aktivierung von PPAR-γ). Damit der Wirkstoff dort ankommt, wo die Entzündung sitzt, wird er in magensaftresistenten oder retardierten Tabletten und Granulaten im Dünndarm bzw. Dickdarm freigesetzt oder als Zäpfchen, Einlauf oder Schaum rektal angewendet. Der aufgenommene Anteil wird in Darmwand und Leber acetyliert und über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Durchfall, Bauchschmerzen, Blähungen","Übelkeit, Erbrechen","Kopfschmerzen","Hautausschlag"],"gelegentlich":["Juckreiz, Nesselsucht"],"selten":["Schwindel","Herzmuskel- und Herzbeutelentzündung (Myokarditis, Perikarditis)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Lichtempfindlichkeit der Haut"],"sehrSelten":["Blutbildveränderungen (Agranulozytose, aplastische Anämie, Thrombozytopenie, Panzytopenie)","Interstitielle Nephritis (Nierenentzündung), nephrotisches Syndrom, Nierenversagen","Allergische Lungenentzündung, Lungenfibrose","Hepatitis, Gallestau","Periphere Nervenschädigung (Neuropathie)","Lupus-ähnliches Syndrom, Muskel- und Gelenkschmerzen","Haarausfall","Vorübergehend verminderte Spermienzahl"],"unbekannt":["Nierensteine","Schwere Hautreaktionen (DRESS, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Akute Unverträglichkeit mit Verschlechterung der Darmbeschwerden (Krämpfe, blutiger Durchfall, Fieber)","Idiopathische intrakranielle Hypertonie (erhöhter Hirndruck mit Kopfschmerz und Sehstörungen)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden; umfangreiche Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich – auf Durchfall beim Säugling achten.","hinweise":["Nierenwerte und Urin vor Beginn und dann regelmässig kontrollieren lassen, ebenso das Blutbild.","Tabletten und Granulat unzerkaut schlucken.","Bei Krämpfen, Fieber, starken Kopfschmerzen oder Hautausschlag kurz nach Beginn ärztlich melden (mögliche Unverträglichkeit).","Ausreichend trinken (beugt Nierensteinen vor)."],"darreichung":["Magensaftresistente Tabletten","Retardtabletten","Retardgranulat (Beutel)","Suppositorien (Zäpfchen)","Klysma (Einlauf)","Rektalschaum"]},"mesna":{"wirkmechanismus":"Entgiftet in der Blase schädliche Abbauprodukte bestimmter Chemotherapie-Mittel. Ifosfamid und Cyclophosphamid bilden unter anderem Acrolein, das die Blasenschleimhaut angreift und eine blutige Blasenentzündung (hämorrhagische Zystitis) auslösen kann. Mesna liegt im Blut als unwirksames Dimer vor, wird in der Niere wieder zur freien Thiolverbindung reduziert und bindet im Urin Acrolein zu einer ungiftigen Verbindung. Die Wirkung der Chemotherapie gegen den Tumor wird dadurch nicht beeinträchtigt.","nebenwirkungen":{"unbekannt":["Kopfschmerzen, Müdigkeit, Schwindel","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Hautausschlag, Juckreiz, Hautrötung","Reaktionen an der Injektionsstelle","Grippeähnliche Beschwerden, Fieber","Unangenehmer Geschmack (Tabletten)","Schwere Haut- und Überempfindlichkeitsreaktionen (Anaphylaxie, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Blutdruckabfall, Herzrasen"]},"schwangerschaft":"Keine ausreichenden Daten beim Menschen; in Tierversuchen keine fruchtschädigende Wirkung. Anwendung im Rahmen einer notwendigen Chemotherapie nach ärztlicher Abwägung.","stillzeit":"Nicht bekannt, ob Mesna in die Muttermilch übergeht; während der Chemotherapie nicht stillen.","hinweise":["Während und nach der Chemotherapie reichlich trinken und die Blase regelmässig entleeren.","Rötlichen Urin oder Blut im Urin sofort melden.","Mesna kann Urintests auf Ketonkörper falsch positiv machen."],"darreichung":["Injektionslösung","Filmtabletten"]},"mesuximid":{"wirkmechanismus":"Dämpft die übermässige, rhythmische Aktivität von Nervenzellen, die Absencen auslöst. Mesuximid wird in der Leber zum langsam ausgeschiedenen Hauptwirkstoff N-Desmethylmesuximid umgewandelt. Wie Ethosuximid hemmt es T-Typ-Calciumkanäle in Nervenzellen des Thalamus und unterdrückt so die für Absencen typischen Entladungen.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen","Appetitlosigkeit, Gewichtsabnahme","Schläfrigkeit, Müdigkeit","Schwindel, Gangunsicherheit (Ataxie)","Kopfschmerzen","Schluckauf (Singultus)"],"unbekannt":["Psychische Veränderungen (Verwirrtheit, Reizbarkeit, Depression, Psychosen)","Doppelbilder, Lichtscheu","Blutbildveränderungen bis zu Agranulozytose (Fehlen weisser Blutkörperchen) und aplastischer Anämie","Hautausschlag, Stevens-Johnson-Syndrom (schwere Hautreaktion)","Medikamentös ausgelöster Lupus erythematodes"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung; eine wirksame Behandlung nicht eigenmächtig absetzen. Eine Schwangerschaft möglichst vorher mit der Ärztin oder dem Arzt planen.","stillzeit":"Keine ausreichenden Daten; Stillen nur nach ärztlicher Abwägung und unter Beobachtung des Säuglings (Schläfrigkeit, Trinkschwäche).","hinweise":["Mit dem Essen einnehmen, das mildert Magen-Darm-Beschwerden.","Nicht abrupt absetzen – Gefahr gehäufter Anfälle.","Bei Fieber, Halsschmerzen, Hautausschlag oder Blutungen sofort ärztlich abklären; Blutbild und Leberwerte werden regelmässig kontrolliert.","Kann Reaktionsvermögen und Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Kapseln"]},"metamizol":{"wirkmechanismus":"Lindert starke Schmerzen, senkt Fieber und entspannt verkrampfte glatte Muskulatur, z. B. bei Koliken. Metamizol ist eine Vorstufe, die im Darm zu 4-Methylaminoantipyrin umgewandelt wird; dieses und weitere Abbauprodukte hemmen die Prostaglandinbildung vor allem im Zentralnervensystem und aktivieren schmerzhemmende Bahnen. Die entzündungshemmende Wirkung ist gering, und Magen und Nieren werden weniger belastet als durch NSAR.","nebenwirkungen":{"gelegentlich":["Blutdruckabfall (v. a. bei rascher Injektion)","Fixes Arzneimittelexanthem (Hautausschlag immer an derselben Stelle)"],"selten":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Atemnot)","Leukopenie (Verminderung der weissen Blutkörperchen)","Hautausschlag"],"sehrSelten":["Agranulozytose (lebensgefährlicher Mangel an weissen Blutkörperchen)","Thrombozytopenie (Mangel an Blutplättchen)","Analgetika-Asthma-Anfall","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Akute Nierenfunktionsstörung, interstitielle Nephritis"],"unbekannt":["Anaphylaktischer Schock","Aplastische Anämie, Panzytopenie","Arzneimittelbedingte Leberentzündung (Hepatitis)","DRESS (schwere Arzneimittelreaktion mit Fieber und Organbeteiligung)","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Rotfärbung des Urins (harmlos)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach strenger ärztlicher Abwägung; im letzten Drittel kontraindiziert (Gefahr eines vorzeitigen Verschlusses des Ductus arteriosus beim Kind und von Gerinnungsstörungen).","stillzeit":"Abbauprodukte gehen in die Muttermilch über. Wiederholte Anwendung vermeiden; nach einer Einzeldosis 48 Stunden nicht stillen und die Milch verwerfen.","hinweise":["Bei Fieber, Halsschmerzen, Schluckbeschwerden oder Entzündungen im Mund während oder kurz nach der Einnahme sofort ärztliche Hilfe holen und ein Blutbild machen lassen.","Bei längerer Anwendung regelmässige Blutbildkontrollen.","Eine Rotfärbung des Urins durch ein Abbauprodukt ist harmlos.","Injektionen nur langsam und im Liegen verabreichen (Blutdruckabfall)."],"darreichung":["Filmtabletten","Tropfen (Lösung zum Einnehmen)","Zäpfchen","Injektionslösung"]},"metformin":{"wirkmechanismus":"Senkt den erhöhten Blutzucker, vor allem indem es die Zuckerneubildung in der Leber bremst. Metformin hemmt die Glukoneogenese und den Glykogenabbau in der Leber (unter anderem über die mitochondriale Atmungskette und die AMP-aktivierte Proteinkinase), verbessert die Insulinempfindlichkeit der Muskulatur und verzögert die Zuckeraufnahme im Darm. Weil es die Insulinausschüttung nicht steigert, verursacht es allein keine Unterzuckerung und begünstigt keine Gewichtszunahme. Es wird unverändert über die Nieren ausgeschieden; bei eingeschränkter Nierenfunktion reichert es sich an und kann eine Laktatazidose (gefährliche Übersäuerung des Blutes) auslösen.","nebenwirkungen":{"sehrHaeufig":["Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Durchfall, Bauchschmerzen und Appetitlosigkeit (vor allem zu Behandlungsbeginn, meist vorübergehend)"],"haeufig":["Geschmacksstörung (z. B. metallischer Geschmack)","Vitamin-B12-Mangel bzw. erniedrigter Vitamin-B12-Spiegel bei Langzeitbehandlung (kann zu Blutarmut oder Nervenschäden führen)"],"sehrSelten":["Laktatazidose (lebensbedrohliche Übersäuerung des Blutes)","Hautreaktionen wie Rötung, Juckreiz, Nesselsucht","Veränderte Leberwerte oder Hepatitis (Leberentzündung), nach Absetzen rückläufig"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko. Bei Kinderwunsch oder Schwangerschaft wird die Diabetesbehandlung ärztlich überprüft; häufig wird Insulin eingesetzt.","stillzeit":"Nicht empfohlen: Metformin geht in geringer Menge in die Muttermilch über; beim gestillten Kind wurden bisher keine Wirkungen beobachtet, die Daten sind aber begrenzt. Ärztliche Nutzen-Risiko-Abwägung.","hinweise":["Zu oder nach den Mahlzeiten einnehmen; die Dosis wird langsam gesteigert, damit Magen-Darm-Beschwerden seltener auftreten.","Bei Erbrechen, Durchfall, hohem Fieber oder wenn kaum getrunken werden kann, Metformin pausieren und ärztlichen Rat einholen.","Vor Operationen und Untersuchungen mit Kontrastmittel die Einnahme von Metformin angeben.","Nierenfunktion mindestens einmal jährlich und bei Langzeitbehandlung den Vitamin-B12-Spiegel kontrollieren lassen."],"darreichung":["Filmtabletten","Retardtabletten (in Kombinationspräparaten)"]},"methadon":{"wirkmechanismus":"Lindert starke Schmerzen und verhindert bei Opioidabhängigkeit Entzugssymptome und Suchtdruck. Methadon ist ein voller Agonist am µ-Opioidrezeptor und hemmt zusätzlich NMDA-Rezeptoren sowie die Wiederaufnahme von Serotonin und Noradrenalin. Die Halbwertszeit ist lang und individuell sehr unterschiedlich (etwa 15 bis über 60 Stunden): Bei der Substitution genügt eine Dosis pro Tag, nach Dosissteigerungen kann sich Methadon aber über Tage anreichern. Abgebaut wird es vor allem über CYP3A4 und CYP2B6.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen"],"haeufig":["Verstopfung","Sedierung (Dämpfung), Müdigkeit","Euphorie, Halluzinationen","Verschwommenes Sehen, enge Pupillen, trockene Augen","Drehschwindel","Schwitzen, vorübergehender Hautausschlag","Wassereinlagerungen, Gewichtszunahme"],"gelegentlich":["Dysphorie (Missstimmung), Unruhe, Schlaflosigkeit, Desorientiertheit","Verminderte Libido, Potenz- und Menstruationsstörungen","Kopfschmerzen, Ohnmacht","Tiefer Blutdruck, Hautrötung (Flush)","Harnverhalt","Gallenwegskrämpfe","Mundtrockenheit, Juckreiz, Nesselsucht","Lungenödem, Verschlechterung eines Asthmas"],"selten":["QT-Verlängerung, Torsade de pointes (lebensbedrohliche Herzrhythmusstörung)","Bradykardie (langsamer Puls), Herzklopfen"],"unbekannt":["Atemdepression (Atemschwäche), vor allem bei Überdosierung","Hypoglykämie (Unterzuckerung)","Hypokaliämie, Hypomagnesiämie","Abhängigkeit, Entzugssymptome beim Absetzen","Schlafbezogene Atemstörungen (zentrale Schlafapnoe)","Nebenniereninsuffizienz, verminderte Sexualhormone bei Langzeitgebrauch"]},"schwangerschaft":"Eine Substitution wird in der Schwangerschaft unter enger ärztlicher Betreuung fortgeführt, da sie sicherer ist als ein unkontrollierter Konsum oder Entzug; beim Neugeborenen ist mit Entzugssymptomen zu rechnen.","stillzeit":"Geht in die Muttermilch über; bei stabiler Dosis ist Stillen nach ärztlicher Abwägung möglich – das Kind auf Schläfrigkeit und Atemprobleme beobachten.","hinweise":["Untersteht dem Betäubungsmittelgesetz: sicher und für Kinder unzugänglich aufbewahren – schon kleine Mengen können für Kinder und Nicht-Gewöhnte tödlich sein.","Keine Beruhigungs- oder Schlafmittel und keinen Alkohol ohne ärztliche Rücksprache einnehmen (Atemstillstand möglich).","Regelmässige EKG-Kontrollen, besonders bei hohen Dosen oder neuen Begleitmedikamenten.","Die Fahrtüchtigkeit ist zu Beginn und bei Dosisänderungen eingeschränkt."],"darreichung":["Tabletten","Lösung zum Einnehmen","Injektionslösung"]},"methotrexat":{"wirkmechanismus":"Bremst das überaktive Immunsystem und – in hoher Dosis – die Teilung von Krebszellen. Methotrexat hemmt als Folsäure-Antagonist die Dihydrofolat-Reduktase und damit die Bildung von Tetrahydrofolat, das für die DNA-Synthese nötig ist. In niedriger, wöchentlicher Dosis beruht die entzündungshemmende Wirkung vor allem auf einer Anreicherung von Adenosin und der Hemmung aktivierter Immunzellen. Folinsäure (Calciumfolinat) umgeht die Blockade und dient nach Hochdosistherapie und bei Überdosierung als Gegenmittel.","nebenwirkungen":{"sehrHaeufig":["Entzündung der Mundschleimhaut (Stomatitis)","Übelkeit, Appetitlosigkeit, Bauchschmerzen, Verdauungsbeschwerden","Erhöhte Leberwerte"],"haeufig":["Mundgeschwüre, Durchfall","Leukopenie, Anämie, Thrombozytopenie (Blutbildveränderungen)","Kopfschmerzen, Müdigkeit, Benommenheit","Lungenentzündung durch Methotrexat (interstitielle Pneumonitis)","Hautausschlag, Rötung, Juckreiz"],"gelegentlich":["Panzytopenie (Mangel aller Blutzellen)","Magen-Darm-Geschwüre und -Blutungen, Erbrechen","Leberfibrose und -zirrhose","Haarausfall, Lichtempfindlichkeit, Nesselsucht","Herpes zoster (Gürtelrose)","Gelenk- und Muskelschmerzen, Osteoporose","Schwindel, Verwirrtheit, Depression"],"selten":["Lungenfibrose, Pleuraerguss","Herzbeutelentzündung (Perikarditis)","Akute Hepatitis","Nierenversagen","Blutgerinnsel (Thromboembolien)","Ermüdungsbrüche","Erythema multiforme (Hautreaktion)"],"sehrSelten":["Agranulozytose (Ausfall der weissen Blutkörperchen) und schwere Knochenmarkhemmung","Leberversagen","Lymphome (Lymphknotenkrebs), teils nach Absetzen rückläufig","Schwere Infektionen (z. B. Pneumocystis-Pneumonie, Zytomegalie, Sepsis)","Toxisches Megakolon"],"unbekannt":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Anaphylaxie (schwere allergische Reaktion)","Progressive multifokale Leukenzephalopathie (PML, Hirninfektion)","Enzephalopathie (Hirnschädigung), vor allem bei hoher Dosis"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend, Fehlgeburten). Frauen müssen während und mindestens 6 Monate nach Therapieende zuverlässig verhüten; Männer bzw. ihre Partnerinnen vorsorglich während und mindestens 3 Monate danach.","stillzeit":"Kontraindiziert; vor Behandlungsbeginn abstillen.","hinweise":["Bei Rheuma, Psoriasis und Morbus Crohn nur EINMAL PRO WOCHE an einem festen Wochentag anwenden – versehentliche tägliche Einnahme hat zu tödlichen Vergiftungen geführt.","Folsäure (nach ärztlicher Verordnung, meist am Folgetag) vermindert Nebenwirkungen.","Regelmässige Kontrollen von Blutbild, Leber- und Nierenwerten; Alkohol meiden.","Bei Fieber, Husten, Atemnot, Mundgeschwüren oder Durchfall sofort ärztlich melden."],"darreichung":["Tabletten","Injektionslösung in Fertigspritze oder Fertigpen","Injektions- und Infusionslösung"]},"methoxy-polyethylenglycol-epoetin-beta":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Der Wirkstoff aktiviert wie das körpereigene Erythropoetin den Erythropoetin-Rezeptor auf den Vorläuferzellen der roten Blutkörperchen im Knochenmark. Durch die Kopplung an eine grosse Polyethylenglycol-Kette wird er sehr langsam ausgeschieden (Halbwertszeit über 100 Stunden), weshalb eine Injektion alle 2 bis 4 Wochen genügt.","nebenwirkungen":{"haeufig":["Bluthochdruck (Hypertonie)"],"gelegentlich":["Kopfschmerzen","Thrombose des Dialyse-Gefässzugangs (Shunt)"],"selten":["Hypertensive Enzephalopathie (Hirnfunktionsstörung durch sehr hohen Blutdruck)","Überempfindlichkeitsreaktionen","Hautausschlag","Hitzewallungen"],"unbekannt":["Erythroblastopenie (PRCA, Ausfall der Bildung roter Blutkörperchen durch Antikörper)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","Thrombozytopenie (Mangel an Blutplättchen)","Thromboembolische Ereignisse, Schlaganfall, Herzinfarkt (bei zu hohem Hämoglobin)","Krampfanfälle"]},"schwangerschaft":"Keine Erfahrungen bei Schwangeren; im Tierversuch keine direkten schädlichen Wirkungen. Nur nach sorgfältiger ärztlicher Abwägung anwenden.","stillzeit":"Unbekannt, ob der Wirkstoff in die Muttermilch übergeht; Entscheid zwischen Abstillen und Therapieverzicht nach ärztlicher Abwägung.","hinweise":["Hämoglobin und Blutdruck regelmässig kontrollieren; der Zielwert des Hämoglobins (in der Regel 10–12 g/dl) soll nicht überschritten werden.","Eisenstatus kontrollieren – meist ist zusätzlich Eisen nötig.","Bei starken Kopfschmerzen, Verwirrtheit oder Krampfanfällen (Blutdruckkrise) sofort den Notfall aufsuchen."],"darreichung":["Injektionslösung in Fertigspritze"]},"methoxyfluran":{"wirkmechanismus":"Lindert Schmerzen bereits nach wenigen Atemzügen, ohne in der verwendeten niedrigen Dosis eine Narkose auszulösen. Methoxyfluran ist ein fluoriertes Inhalationsanästhetikum, das über die Lunge aufgenommen wird und im zentralen Nervensystem schmerzlindernd wirkt; der genaue Mechanismus ist nicht vollständig geklärt. Beim Abbau in der Leber (über CYP2E1 und CYP2A6) entstehen anorganisches Fluorid und Dichloressigsäure, die in höheren Dosen die Nieren schädigen. Deshalb sind Tages- und Wochendosis streng begrenzt.","nebenwirkungen":{"sehrHaeufig":["Schwindel"],"haeufig":["Benommenheit, Schläfrigkeit, Kopfschmerzen","Euphorie, Angst, Trunkenheitsgefühl","Geschmacksstörungen","Übelkeit, Erbrechen","Husten","Blutdruckabfall","Schwitzen"],"gelegentlich":["Doppeltsehen, Kribbeln (Parästhesien)","Müdigkeit, Schüttelfrost"],"unbekannt":["Leberschäden (Hepatitis, Gelbsucht, Leberversagen)","Nierenschäden bis Nierenversagen","Bewusstseinsstörungen","Atemdepression, Sauerstoffmangel"]},"schwangerschaft":"Nicht empfohlen; Anwendung nur nach strenger ärztlicher Abwägung. Kann die Wehentätigkeit und das Neugeborene beeinflussen.","stillzeit":"Ungenügende Daten; nach einer einmaligen Notfallanwendung Vorgehen ärztlich besprechen.","hinweise":["Höchstens 6 ml (2 Fläschchen) pro Tag, nicht an aufeinanderfolgenden Tagen und höchstens 15 ml pro Woche (Schutz der Nieren).","Nur unter Aufsicht von geschultem Personal; die betroffene Person hält den Inhalator selbst.","Nach der Anwendung nicht Auto fahren, bis die Wirkung vollständig abgeklungen ist."],"darreichung":["Flüssigkeit zur Herstellung eines Dampfs zur Inhalation (mit Inhalator)"]},"methylaminolevulinat":{"wirkmechanismus":"Macht krankhaft veränderte Hautzellen lichtempfindlich, sodass sie bei Bestrahlung mit Rotlicht oder Tageslicht absterben. Methylaminolevulinat wird bevorzugt von Tumorzellen und Krebsvorstufen aufgenommen und dort zu Protoporphyrin IX umgewandelt, das sich in diesen Zellen anreichert. Bei Belichtung mit passender Wellenlänge entstehen daraus reaktive Sauerstoffverbindungen (Singulett-Sauerstoff), die die Zellen zerstören.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Brennen an der behandelten Stelle (v. a. während der Belichtung)","Rötung","Krustenbildung","Juckreiz","Schwellung","Hautkribbeln (Parästhesie)"],"haeufig":["Blasen","Hautgeschwür und Hauterosion","Hautinfektion an der behandelten Stelle","Abschuppung","Blutung an der behandelten Stelle","Kopfschmerzen"],"gelegentlich":["Nesselsucht (Urtikaria)","Lidschwellung, Augenschmerzen"],"unbekannt":["Angioödem (Schwellung von Haut und Schleimhäuten)","Allergische Kontaktdermatitis","Pigmentveränderungen der Haut"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn unbedingt nötig.","stillzeit":"Nach der Anwendung 48 Stunden nicht stillen.","hinweise":["Die Behandlung wird von Fachpersonen durchgeführt; Brennen und Schmerzen während der Belichtung lassen sich durch Kühlen oder Pausen lindern.","Behandelte Stellen etwa 2 Tage vor Sonne und starkem Licht schützen.","Bei Tageslicht-Therapie vorher nur einen Sonnenschutz ohne mineralische Filter (z. B. ohne Titandioxid) auftragen."],"darreichung":["Creme"]},"methyldopa":{"wirkmechanismus":"Senkt den Blutdruck, indem es im Gehirn die Aktivität des Sympathikus (des «Stressnervensystems») dämpft. Methyldopa ist ein Prodrug: In Nervenzellen wird es zu Alpha-Methylnoradrenalin umgewandelt, das zentrale Alpha-2-Rezeptoren im Hirnstamm stimuliert. Dadurch sinken der Sympathikustonus, der periphere Gefässwiderstand und der Blutdruck, ohne dass Herzleistung und Nierendurchblutung wesentlich abnehmen.","nebenwirkungen":{"unbekannt":["Müdigkeit, Benommenheit, Kopfschmerzen und Schwächegefühl, besonders zu Beginn","Schwindel und Blutdruckabfall beim Aufstehen, Bradykardie (langsamer Puls)","Mundtrockenheit, verstopfte Nase, Ödeme (Wassereinlagerungen)","Depression, Albträume","Potenzstörungen, Brustvergrösserung oder Milchfluss (erhöhtes Prolaktin)","Positiver Coombs-Test (bei 10–20 % unter Langzeitbehandlung), hämolytische Anämie (Blutzerfall)","Hepatitis (Leberentzündung), Gelbsucht, Arzneimittelfieber","Agranulozytose (starker Mangel an weissen Blutkörperchen), Thrombozytopenie, Pankreatitis"]},"schwangerschaft":"Gilt dank langer Erfahrung als Mittel der Wahl gegen Bluthochdruck in der Schwangerschaft; Anwendung nach ärztlicher Verordnung.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Blutbild und Leberwerte vor allem in den ersten 6–12 Wochen kontrollieren; bei Fieber, Gelbsucht oder ungewohnter Müdigkeit ärztlich abklären.","Kann müde machen – Vorsicht beim Autofahren; Alkohol verstärkt die Wirkung.","Vor Bluttransfusionen die Einnahme angeben (der Coombs-Test kann positiv sein).","Nicht eigenmächtig absetzen; der Urin kann sich an der Luft dunkel färben."],"darreichung":["Filmtabletten"]},"methylergometrin":{"wirkmechanismus":"Bewirkt eine kräftige, anhaltende Zusammenziehung der Gebärmutter und stillt dadurch Blutungen. Methylergometrin ist ein halbsynthetisches Mutterkornalkaloid, das an Serotonin-, Alpha-adrenerge und Dopamin-Rezeptoren der glatten Muskulatur wirkt. Es erhöht Grundtonus, Stärke und Häufigkeit der Uteruskontraktionen. Daneben verengt es Blutgefässe, was den Blutdruck steigern kann. Der Abbau erfolgt über CYP3A4 in der Leber.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bluthochdruck","Hautausschlag","Bauchschmerzen (durch Gebärmutterkontraktionen)"],"gelegentlich":["Schwindel, Krampfanfälle","Brustschmerzen","Blutdruckabfall","Übelkeit, Erbrechen","Vermehrtes Schwitzen"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Halluzinationen","Herzinfarkt, Krämpfe der Herzkranzgefässe","Bradykardie oder Herzrasen, Herzklopfen","Gefässkrämpfe in Armen und Beinen","Muskelkrämpfe"],"sehrSelten":["Ohrensausen","Verstopfte Nase","Durchfall","Thrombophlebitis (Venenentzündung)"]},"schwangerschaft":"Während der Schwangerschaft und vor der Geburt des Kindes kontraindiziert (Gefahr eines Dauerkrampfes der Gebärmutter und Schädigung des Kindes).","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; Stillen während der Behandlung und bis 12 Stunden nach der letzten Dosis nicht empfohlen. Nur kurzzeitig anwenden.","hinweise":["Wird in der Regel im Spital nach der Geburt verabreicht; Blutdruck wird überwacht.","Bei Brustschmerzen, kalten oder gefühllosen Fingern und Zehen oder starken Kopfschmerzen sofort ärztliche Hilfe holen.","Ärztin oder Arzt über alle eingenommenen Medikamente informieren, besonders Antibiotika, HIV- und Pilzmittel."],"darreichung":["Injektionslösung","Tabletten (Dragées)"]},"methylnaltrexon":{"wirkmechanismus":"Hebt die verstopfende Wirkung von Opioid-Schmerzmitteln im Darm auf, ohne die Schmerzlinderung zu beeinträchtigen. Methylnaltrexon blockiert die µ-Opioidrezeptoren in der Darmwand und normalisiert so Darmbewegung und Flüssigkeitshaushalt im Darm. Als quartäre Ammoniumverbindung überwindet es die Blut-Hirn-Schranke kaum und wirkt daher nur ausserhalb des Gehirns.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Übelkeit","Durchfall","Blähungen"],"haeufig":["Schwindel","Erbrechen","Opioid-entzugsähnliche Beschwerden (z. B. Frösteln, Zittern, Schwitzen, Herzklopfen, laufende Nase)","Reaktionen an der Einstichstelle (Brennen, Schmerz, Rötung, Schwellung)"],"unbekannt":["Magen-Darm-Perforation (Durchbruch der Darmwand)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung anwenden (beim Ungeborenen sind Entzugssymptome denkbar).","stillzeit":"Nicht bekannt, ob Methylnaltrexon beim Menschen in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird unter die Haut von Bauch, Oberschenkel oder Oberarm gespritzt; Einstichstelle wechseln.","Der Stuhlgang kann schon kurz nach der Injektion einsetzen – eine Toilette sollte in der Nähe sein.","Wird das Opioid-Schmerzmittel abgesetzt, ist auch Methylnaltrexon nicht mehr nötig.","Starke oder anhaltende Bauchschmerzen sofort ärztlich melden."],"darreichung":["Injektionslösung zur Anwendung unter die Haut"]},"methylphenidat":{"wirkmechanismus":"Verbessert Aufmerksamkeit und Konzentration und vermindert Hyperaktivität und Impulsivität, indem es die Botenstoffe Dopamin und Noradrenalin im Gehirn länger wirken lässt. Methylphenidat blockiert die Transporter für die Wiederaufnahme von Dopamin und Noradrenalin in die Nervenzelle, vor allem im Stirnhirn und im Striatum. Anders als Amphetamine setzt es die Botenstoffe kaum aktiv frei. Es wird durch die Carboxylesterase 1 (nicht über CYP-Enzyme) rasch zur unwirksamen Ritalinsäure abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Nervosität","Kopfschmerzen"],"haeufig":["Appetitminderung, verminderte Gewichts- und Grössenzunahme bei Kindern","Reizbarkeit, Stimmungsschwankungen, Unruhe, Angst, Aggressivität, Depression","Schwindel, Schläfrigkeit, Dyskinesien (unwillkürliche Bewegungen)","Herzrasen, Herzklopfen, Herzrhythmusstörungen, Blutdruckanstieg","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Mundtrockenheit","Haarausfall, Juckreiz, Hautausschlag, Nesselsucht","Gelenkschmerzen, Fieber","Husten, Halsschmerzen, Nasen-Rachen-Entzündung"],"gelegentlich":["Psychotische Störungen, Halluzinationen","Suizidgedanken","Tics oder Verschlechterung bestehender Tics bzw. eines Tourette-Syndroms","Zittern (Tremor), Doppeltsehen, verschwommenes Sehen","Brustschmerzen, Atemnot","Überempfindlichkeitsreaktionen (Angioödem, Anaphylaxie)","Erhöhte Leberwerte","Muskelschmerzen, Muskelzucken"],"selten":["Manie, Desorientierung","Angina pectoris (Brustenge)","Pupillenerweiterung, Akkommodationsstörungen","Gynäkomastie (Brustvergrösserung beim Mann)"],"sehrSelten":["Suizidversuch","Krampfanfälle, malignes neuroleptisches Syndrom","Herzinfarkt, Herzstillstand, plötzlicher Herztod","Zerebrale Arteriitis oder Gefässverschluss, Raynaud-Phänomen","Leberfunktionsstörungen bis Leberkoma","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)","Erythema multiforme, exfoliative Dermatitis"],"unbekannt":["Abhängigkeit, Missbrauch","Hirnblutung, Schlaganfall","Priapismus (schmerzhafte Dauererektion)","Wahnvorstellungen, Verwirrtheit","Panzytopenie"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Daten deuten auf ein möglicherweise leicht erhöhtes Risiko für Herzfehlbildungen hin.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung (abstillen oder Behandlung unterbrechen).","hinweise":["Untersteht dem Betäubungsmittelgesetz: sicher aufbewahren, nicht weitergeben.","Retardtabletten unzerkaut schlucken; Ritalin-LA- und Medikinet-MR-Kapseln dürfen geöffnet und der Inhalt auf etwas Apfelmus gestreut werden. Die leere Tablettenhülle von Concerta kann im Stuhl erscheinen.","Puls, Blutdruck, Gewicht, Appetit und bei Kindern die Körpergrösse regelmässig kontrollieren; die Notwendigkeit der Behandlung periodisch überprüfen.","Am Tag einer Operation mit Narkose nicht einnehmen; Alkohol meiden."],"darreichung":["Tabletten","Retardtabletten","Retardkapseln"]},"methylprednisolon":{"wirkmechanismus":"Dämpft Entzündungen, Allergien und überschiessende Immunreaktionen. Methylprednisolon ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und die Ablesung zahlreicher Gene verändert: Die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) wird gehemmt und die Aktivität von T-Zellen und anderen Abwehrzellen herabgesetzt. 4 mg Methylprednisolon entsprechen etwa 5 mg Prednisolon; die salzspeichernde (mineralokortikoide) Wirkung ist gering. Das in Hautpräparaten verwendete Methylprednisolonaceponat wird erst in der Haut in seine wirksame Form umgewandelt und gelangt kaum in den Blutkreislauf.","nebenwirkungen":{"haeufig":["Hautpräparate: Brennen und Juckreiz an der Auftragsstelle"],"gelegentlich":["Hautpräparate: Trockenheit, Rötung, Bläschen, Haarbalgentzündung (Follikulitis), Ausschlag, Kribbeln der Haut"],"unbekannt":["Erhöhte Infektanfälligkeit, Verschleierung von Infektionen","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht) und Unterdrückung der Nebennierenfunktion bei längerer Anwendung","Erhöhter Blutzucker bis Diabetes, Hypokaliämie (Kaliummangel), Wassereinlagerungen, Bluthochdruck","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche (Steroidmyopathie), Sehnenriss, Wachstumsverzögerung bei Kindern","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis (Bauchspeicheldrüsenentzündung)","Psychische Veränderungen: Euphorie, Schlaflosigkeit, Stimmungsschwankungen, Depression, Psychosen","Grauer und grüner Star (Katarakt, Glaukom), verschwommenes Sehen (Chorioretinopathie)","Hautverdünnung, Dehnungsstreifen, Akne, verzögerte Wundheilung (auch bei langer Anwendung der Hautpräparate)","Herzrhythmusstörungen oder Kreislaufkollaps bei rascher Infusion hoher Dosen; Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei längerer Behandlung sind Wachstumsverzögerung des Kindes und eine Nebennierenschwäche beim Neugeborenen möglich; Hautpräparate nicht grossflächig oder langfristig anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; eine kurzfristige Behandlung in üblicher Dosis ist nach ärztlicher Abwägung möglich, bei hohen Dosen Rücksprache halten. Hautpräparate nicht auf die Brust auftragen.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen – das schont die körpereigene Kortisonbildung.","Nach längerer Behandlung nie abrupt absetzen, sondern nach ärztlichem Plan ausschleichen.","Bei Langzeitbehandlung Blutzucker, Blutdruck, Kalium, Knochendichte und Augeninnendruck kontrollieren lassen.","Hautpräparate bei Erwachsenen höchstens 12 Wochen, bei Kindern höchstens 4 Wochen ohne Unterbruch anwenden; nicht unter luftdichten Verbänden."],"darreichung":["Tabletten","Pulver und Lösungsmittel zur Herstellung einer Injektions-/Infusionslösung","Kristallsuspension zur Injektion (Depot)","Creme","Salbe","Fettsalbe","Emulsion (Milch)"]},"methylthioniniumchlorid":{"wirkmechanismus":"Hilft dem roten Blutfarbstoff, wieder Sauerstoff zu transportieren. Im Körper wird Methylthioniniumchlorid durch die NADPH-abhängige Methämoglobin-Reduktase zu Leukomethylenblau reduziert; dieses wandelt das dreiwertige Eisen des Methämoglobins wieder in zweiwertiges Eisen um, sodass normales Hämoglobin entsteht. Dafür braucht es NADPH aus dem Pentosephosphatweg – bei G6PD-Mangel wirkt es deshalb nicht und kann Blutzerfall auslösen. Zudem hemmt es stark das Enzym Monoaminoxidase A.","nebenwirkungen":{"sehrHaeufig":["Blau-grüne Verfärbung des Urins"],"haeufig":["Blaufärbung der Haut","Schwindel, Kopfschmerzen","Missempfindungen (Kribbeln), Geschmacksstörung","Übelkeit","Vermehrtes Schwitzen","Schmerzen in Armen oder Beinen"],"unbekannt":["Serotoninsyndrom (zusammen mit serotonergen Mitteln)","Hämolytische Anämie (Blutzerfall), besonders bei G6PD-Mangel","Methämoglobinämie bei zu hohen Dosen","Anaphylaxie (schwere allergische Reaktion)","Herzrhythmusstörungen, Blutdruckanstieg oder -abfall","Verwirrtheit, Unruhe, Zittern","Lichtempfindlichkeit der Haut","Gewebeschäden (Nekrosen) an der Injektionsstelle"]},"schwangerschaft":"Nur bei lebensbedrohlicher Methämoglobinämie, wenn eindeutig notwendig: Methylthioniniumchlorid kann dem Ungeborenen schaden.","stillzeit":"Nach der Gabe bis zu 6 Tage nicht stillen.","hinweise":["Urin und Stuhl können sich blau-grün, die Haut bläulich verfärben – das ist harmlos und vorübergehend.","Nach der Behandlung starke Lichtquellen und intensive Sonne meiden (mögliche Lichtempfindlichkeit der Haut).","Alle eingenommenen Antidepressiva angeben (Gefahr eines Serotoninsyndroms)."],"darreichung":["Injektionslösung"]},"metoclopramid":{"wirkmechanismus":"Wirkt gegen Übelkeit und regt den Magen an, seinen Inhalt rascher in den Darm weiterzugeben. Metoclopramid blockiert Dopamin-D2-Rezeptoren in der Brechreizzone des Hirnstamms (Chemorezeptor-Triggerzone) und im Magen-Darm-Trakt. Zusätzlich wirkt es als Agonist an 5-HT4-Rezeptoren und in höherer Dosis als 5-HT3-Antagonist; dadurch werden die Acetylcholin-Freisetzung im Darm gefördert, die Magenentleerung beschleunigt und der Druck des unteren Speiseröhren-Schliessmuskels erhöht. Weil es ins Gehirn gelangt, kann es Bewegungsstörungen (extrapyramidale Symptome) und eine erhöhte Prolaktinausschüttung auslösen.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit (Somnolenz)"],"haeufig":["Extrapyramidale Störungen (z. B. Zungen-Schlund-Krämpfe, Blickkrämpfe), besonders bei Kindern und jungen Erwachsenen","Parkinsonismus, Akathisie (Sitzunruhe)","Depression","Durchfall","Schwächegefühl (Asthenie)","Hypotonie (tiefer Blutdruck), vor allem bei Injektion"],"gelegentlich":["Dystonie und Dyskinesie (unwillkürliche Muskelbewegungen)","Hyperprolaktinämie (erhöhtes Prolaktin), Ausbleiben der Regelblutung","Halluzinationen, Bewusstseinsstörungen","Bradykardie (langsamer Puls), vor allem bei Injektion","Überempfindlichkeitsreaktionen"],"selten":["Krampfanfälle, besonders bei Epilepsie","Verwirrtheit","Milchfluss aus der Brust (Galaktorrhö)"],"unbekannt":["Spätdyskinesie (Tardive Dyskinesie), unter Umständen bleibend, vor allem bei längerer Anwendung","Malignes neuroleptisches Syndrom (hohes Fieber, Muskelstarre, Bewusstseinsstörung)","QT-Verlängerung, Torsade de pointes, AV-Block, Herzstillstand kurz nach Injektion","Methämoglobinämie (gestörter Sauerstofftransport im Blut)","Anaphylaxie, Schock","Blutdruckkrise bei Phäochromozytom","Brustvergrösserung beim Mann (Gynäkomastie)"]},"schwangerschaft":"Zahlreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko; Anwendung bei klarer Notwendigkeit möglich. Gegen Ende der Schwangerschaft können beim Neugeborenen Bewegungsstörungen auftreten.","stillzeit":"Geht in die Muttermilch über; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Höchstens 5 Tage anwenden (Risiko bleibender Bewegungsstörungen); Höchstdosis bei Erwachsenen 30 mg pro Tag, zwischen zwei Gaben mindestens 6 Stunden Abstand.","Kann müde machen und die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Bei unwillkürlichen Bewegungen von Zunge, Gesicht, Hals oder Augen sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Injektionslösung","Granulat (Kombination mit Acetylsalicylsäure)"]},"metoprolol":{"wirkmechanismus":"Verlangsamt den Herzschlag und entlastet das Herz, indem es die Wirkung der Stresshormone am Herzen dämpft. Metoprolol blockiert bevorzugt die Beta-1-Rezeptoren des Herzens und senkt so Herzfrequenz, Kontraktionskraft und Sauerstoffverbrauch; zudem hemmt es die Reninfreisetzung in der Niere. In hohen Dosen geht die Beta-1-Selektivität teilweise verloren. Der Abbau erfolgt in der Leber überwiegend über CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit"],"haeufig":["Bradykardie (langsamer Puls)","Schwindel, Kopfschmerzen","Blutdruckabfall beim Aufstehen","Kalte Hände und Füsse","Übelkeit, Bauchschmerzen, Durchfall oder Verstopfung","Atemnot bei Anstrengung","Herzklopfen (Palpitationen)"],"gelegentlich":["Verschlechterung einer Herzinsuffizienz, Ödeme","AV-Block 1. Grades","Depression, Schlafstörungen, Albträume","Bronchospasmus (Verkrampfung der Atemwege)","Hautausschlag, vermehrtes Schwitzen","Gewichtszunahme","Kribbeln (Parästhesien)"],"selten":["Herzrhythmusstörungen","Sehstörungen, trockene oder gereizte Augen","Erektionsstörungen","Haarausfall","Nervosität, Angst"],"sehrSelten":["Verwirrtheit, Gedächtnisstörungen, Halluzinationen","Thrombozytopenie (Mangel an Blutplättchen)","Hepatitis (Leberentzündung)","Gangrän bei vorbestehender schwerer Durchblutungsstörung","Verschlechterung einer Psoriasis","Gelenkschmerzen","Ohrensausen (Tinnitus)","Lichtempfindlichkeit der Haut"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Betablocker können das Wachstum des Kindes beeinträchtigen. Das Neugeborene in den ersten Tagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen in der Regel möglich, den Säugling aber auf Zeichen einer Betablockade (langsamer Puls, Schläfrigkeit) beobachten.","hinweise":["Nicht abrupt absetzen (Gefahr von Angina-pectoris-Anfällen, Herzinfarkt, Blutdruckanstieg) – über 1–2 Wochen ausschleichen.","Retardtabletten nicht zerkauen; sie dürfen meist halbiert werden.","Besonders zu Beginn können Schwindel und Müdigkeit das Fahrvermögen beeinträchtigen, verstärkt mit Alkohol.","Vor Operationen die Einnahme angeben."],"darreichung":["Retardtabletten","Tabletten","Filmtabletten"]},"metronidazol":{"wirkmechanismus":"Tötet Bakterien und Einzeller ab, die ohne Sauerstoff leben. Metronidazol ist eine Vorstufe: Erst in anaeroben Keimen wird seine Nitrogruppe chemisch reduziert, die entstehenden reaktiven Zwischenprodukte zerstören die Erbsubstanz (DNA) des Erregers. Deshalb wirkt es gezielt gegen Anaerobier (z. B. Bacteroides, Clostridien) und Protozoen wie Trichomonaden, Amöben und Lamblien, nicht aber gegen sauerstoffliebende Bakterien. Bei Rosazea beruht die Wirkung vermutlich auf entzündungshemmenden Effekten.","nebenwirkungen":{"haeufig":["Metallischer oder bitterer Geschmack, belegte Zunge","Übelkeit, Appetitlosigkeit, Magendrücken, Durchfall","Bei Gel oder Creme: trockene Haut, Rötung, Juckreiz, Brennen"],"gelegentlich":["Kopfschmerzen, Schwindel","Hautausschlag, Juckreiz","Dunkelfärbung des Urins (harmlos)"],"sehrSelten":["Agranulozytose, Neutropenie, Thrombozytopenie, Panzytopenie","Enzephalopathie (Gehirnfunktionsstörung), Kleinhirnsyndrom mit Gangunsicherheit und Sprachstörungen, Krampfanfälle","Verwirrtheit, Halluzinationen, psychotische Reaktionen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis, Gelbsucht, Leberversagen","Erbrechen, Muskel- und Gelenkschmerzen, Sehstörungen"],"unbekannt":["Periphere Neuropathie (Kribbeln, Taubheit) bei längerer oder hoch dosierter Anwendung","Aseptische Meningitis, Schädigung des Sehnervs, Hörverlust, Tinnitus","Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), fixes Arzneimittelexanthem","QT-Verlängerung","Pilzinfektionen (Candida im Mund oder in der Scheide)"]},"schwangerschaft":"Geht über die Plazenta; ein Fehlbildungsrisiko beim Menschen ist nicht belegt. Im 1. Drittel nur bei zwingender Indikation, im 2. und 3. Drittel nach ärztlicher Abwägung; Gel und Creme nur nach Rücksprache.","stillzeit":"Geht in höheren Konzentrationen in die Muttermilch über. Während der Einnahme bzw. Infusion nicht stillen (nach einer Einzeldosis 12–24 Stunden Stillpause); Gel und Creme nach ärztlicher Abwägung.","hinweise":["Kein Alkohol während der Behandlung und mindestens 48 Stunden danach.","Tabletten während oder nach dem Essen einnehmen; dunkler Urin ist harmlos.","Bei Trichomonaden-Infektion den Partner mitbehandeln.","Bei Kribbeln oder Taubheit in Händen und Füssen, Gangunsicherheit oder Verwirrtheit sofort ärztlichen Rat holen."],"darreichung":["Filmtabletten","Infusionslösung","Gel und Creme zum Auftragen auf die Haut"]},"metyrapon":{"wirkmechanismus":"Senkt die Bildung des Stresshormons Kortisol in der Nebennierenrinde. Metyrapon hemmt das Enzym 11-Beta-Hydroxylase (CYP11B1), das den letzten Schritt der Kortisol- und Corticosteronbildung katalysiert; dadurch reichern sich die Vorstufen 11-Desoxycortisol und 11-Desoxycorticosteron an. Beim Test fällt das Kortisol ab, eine gesunde Hypophyse schüttet vermehrt ACTH aus, und ein deutlicher Anstieg von 11-Desoxycortisol zeigt eine intakte ACTH-Reserve an. Die angestauten Vorstufen mit mineralokortikoider und androgener Wirkung erklären Bluthochdruck, Kaliummangel und vermehrte Behaarung bei Langzeitbehandlung.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Schwindel","Benommenheit (Sedierung)","Kopfschmerzen","Blutdruckabfall"],"selten":["Nebennierenrindeninsuffizienz (Kortisolmangel mit Schwäche, Übelkeit, Blutdruckabfall)","Allergische Hautreaktionen","Hirsutismus (vermehrte Behaarung)","Haarausfall"],"sehrSelten":["Knochenmarkdepression (Mangel an Blutzellen)"],"unbekannt":["Bauchschmerzen","Bluthochdruck und Hypokaliämie (Kaliummangel) bei Langzeitbehandlung","Akne"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit: Metyrapon passiert die Plazenta und kann die Steroidbildung beim Ungeborenen beeinträchtigen.","stillzeit":"Es ist nicht bekannt, ob Metyrapon in die Muttermilch übergeht; während der Behandlung nicht stillen.","hinweise":["Mit Milch oder einer Mahlzeit einnehmen, um Übelkeit und Erbrechen zu vermindern.","Kann Schwindel und Benommenheit verursachen – Vorsicht beim Autofahren und Bedienen von Maschinen.","Vor einem Metyrapon-Test alle Medikamente angeben, besonders Kortison, Hormone, Antiepileptika und Psychopharmaka.","Bei Langzeitbehandlung Kortisol, Blutdruck und Kalium regelmässig kontrollieren; Schwäche, Übelkeit oder Schwindel können auf einen Kortisolmangel hinweisen."],"darreichung":["Weichkapseln"]},"mianserin":{"wirkmechanismus":"Hebt die Stimmung und fördert den Schlaf. Mianserin blockiert präsynaptische Alpha-2-Adrenozeptoren und steigert so die Freisetzung von Noradrenalin; die Wiederaufnahme von Botenstoffen hemmt es kaum. Zusätzlich blockiert es Serotonin-5-HT2- und Histamin-H1-Rezeptoren, was die ausgeprägte Müdigkeit erklärt. Es wirkt kaum anticholinerg und ist daher bei Herz-, Augen- oder Prostataproblemen meist besser verträglich als Trizyklika. Abbau in der Leber u. a. über CYP2D6 und CYP3A4.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit (v. a. zu Behandlungsbeginn)"],"unbekannt":["Agranulozytose und andere Blutbildveränderungen (Mangel an weissen Blutkörperchen)","Krampfanfälle","Umschlagen in eine Manie (Hypomanie)","Blutdruckabfall beim Aufstehen","Erhöhte Leberwerte, Gelbsucht","Gelenkschmerzen, Wassereinlagerungen (Ödeme)","Hautausschlag","Brustvergrösserung beim Mann, Milchfluss"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (begrenzte Erfahrungen).","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Bei Fieber, Halsschmerzen, Entzündungen im Mund oder anderen Infektzeichen sofort ärztlich das Blutbild kontrollieren lassen (besonders in den ersten Behandlungsmonaten).","Wegen der dämpfenden Wirkung meist abends einnehmen; Vorsicht beim Autofahren, keinen Alkohol trinken.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anweisung."],"darreichung":["Filmtabletten"]},"micafungin":{"wirkmechanismus":"Schädigt die Zellwand von Pilzen, sodass diese nicht mehr wachsen können oder absterben. Micafungin hemmt nicht-kompetitiv das Enzym 1,3-β-D-Glucan-Synthase, das einen wesentlichen Baustein der Pilzzellwand herstellt. Gegen Candida-Arten wirkt es abtötend (fungizid), gegen Aspergillus wachstumshemmend. Menschliche Zellen besitzen keine solche Zellwand.","nebenwirkungen":{"haeufig":["Blutbildveränderungen (Leukopenie, Neutropenie, Anämie)","Hypokaliämie, Hypomagnesiämie, Hypokalzämie (Mangel an Kalium, Magnesium, Calcium)","Kopfschmerzen","Phlebitis (Venenentzündung an der Infusionsstelle)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Erhöhte Leberwerte","Hautausschlag","Fieber, Schüttelfrost"],"gelegentlich":["Thrombozytopenie, Panzytopenie","Anaphylaktische Reaktionen, Überempfindlichkeit","Herzrasen, Herzklopfen, Blutdruckabfall oder -anstieg, Hitzegefühl (Flush)","Leberversagen, Hepatitis, Gelbsucht, Cholestase (Gallenstau)","Erhöhtes Kreatinin, Verschlechterung einer Niereninsuffizienz","Schlaflosigkeit, Angst, Verwirrtheit, Schwindel","Juckreiz, Nesselsucht"],"selten":["Hämolytische Anämie, Hämolyse (Zerfall roter Blutkörperchen)"],"unbekannt":["Anaphylaktischer Schock","Disseminierte intravasale Gerinnung (Gerinnungsentgleisung)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Akutes Nierenversagen, Leberzellschädigung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Übertritt in die Muttermilch beim Menschen unbekannt; Weiterstillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird im Spital als Infusion über etwa eine Stunde verabreicht; eine zu rasche Infusion kann Unverträglichkeitsreaktionen auslösen.","Leber- und Nierenwerte werden während der Behandlung regelmässig kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"miconazol":{"wirkmechanismus":"Stört den Aufbau der Zellmembran von Pilzen und bringt sie so zum Absterben. Miconazol hemmt das pilzeigene Cytochrom-P450-Enzym Lanosterol-14α-Demethylase und damit die Bildung von Ergosterol, einem wichtigen Baustein der Pilzmembran; zusätzlich wirkt es gegen einige grampositive Bakterien. Vom Mundgel wird ein Teil verschluckt und ins Blut aufgenommen; dort hemmt Miconazol die menschlichen Leberenzyme CYP3A4 und CYP2C9 und kann so den Abbau anderer Arzneimittel stark bremsen. Nach Anwendung auf der Haut oder in der Scheide gelangt nur sehr wenig Wirkstoff ins Blut.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen (Mundgel)","Geschmacksstörungen, Mundtrockenheit, Missempfindungen im Mund (Mundgel)","Juckreiz, Brennen und Reizung im Genitalbereich (Vaginalanwendung)"],"gelegentlich":["Hautbrennen, Hautreizung und Rötung an der Anwendungsstelle (Crème)"],"unbekannt":["Anaphylaxie und Angioödem (Schwellung von Gesicht und Rachen)","Ersticken bei Säuglingen und Kleinkindern (Mundgel)","Hepatitis (Leberentzündung)","Durchfall","Schwere Hautreaktionen wie Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse oder DRESS","Nesselsucht, Hautausschlag, Kontaktekzem"]},"schwangerschaft":"Haut- und Vaginalanwendung nach ärztlicher Abwägung möglich, da nur wenig Wirkstoff ins Blut gelangt. Das Mundgel soll in der Schwangerschaft nur angewendet werden, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Nicht bekannt, ob Miconazol in die Muttermilch übergeht; nur nach ärztlicher Abwägung anwenden und nicht auf die Brust auftragen.","hinweise":["Wer Phenprocoumon (Marcoumar) oder Acenocoumarol (Sintrom) einnimmt, muss vor der Anwendung – auch der Crème oder Vaginalform – die Ärztin oder den Arzt informieren; INR-Kontrollen sind nötig.","Mundgel nach den Mahlzeiten anwenden und möglichst lange im Mund behalten, bevor es geschluckt wird; Zahnprothesen ebenfalls behandeln.","Nach dem Abklingen der Beschwerden noch mindestens eine Woche weiterbehandeln, um Rückfälle zu vermeiden.","Bei Scheidenpilz gegebenenfalls den Partner mitbehandeln; während der Vaginalanwendung keine Latexkondome oder -diaphragmen als alleinigen Schutz verwenden."],"darreichung":["Mundgel","Crème","Vaginalcrème","Vaginalzäpfchen (Ovula)"]},"midazolam":{"wirkmechanismus":"Wirkt rasch beruhigend, angstlösend, schlafanstossend, muskelentspannend und krampflösend. Midazolam verstärkt als Benzodiazepin über eine Bindungsstelle am GABA-A-Rezeptor die Wirkung des hemmenden Botenstoffs GABA. Es wirkt sehr schnell und kurz (Halbwertszeit etwa 1,5–2,5 Stunden) und hinterlässt häufig eine Erinnerungslücke für die Zeit des Eingriffs (anterograde Amnesie). Der Abbau erfolgt in der Leber über CYP3A4.","nebenwirkungen":{"haeufig":["Sedierung, Schläfrigkeit, Bewusstseinsminderung","Atemdepression (abgeschwächte Atmung)","Übelkeit, Erbrechen"],"gelegentlich":["Juckreiz, Hautausschlag, Nesselsucht"],"selten":["Paradoxe Reaktionen: Unruhe, Aggressivität, Wut, Verwirrtheit, Halluzinationen"],"unbekannt":["Atemstillstand, Kehlkopfkrampf (Laryngospasmus)","Blutdruckabfall, verlangsamter Herzschlag, Herzstillstand","Anaphylaxie (schwere allergische Reaktion)","Gedächtnislücken (anterograde Amnesie)","Kopfschmerzen, Schwindel, Gangunsicherheit","Schmerzen, Rötung oder Venenentzündung an der Injektionsstelle","Abhängigkeit und Entzugssymptome nach längerer Anwendung","Stürze und Knochenbrüche bei älteren Menschen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Hohe Dosen im letzten Schwangerschaftsdrittel oder unter der Geburt können beim Neugeborenen Atemprobleme, Muskelschlaffheit, Trinkschwäche und Unterkühlung verursachen.","stillzeit":"Midazolam geht in geringen Mengen in die Muttermilch über; nach einer Gabe 24 Stunden lang nicht stillen.","hinweise":["Nach einer Sedierung am selben Tag kein Fahrzeug lenken, keine Maschinen bedienen und nicht ohne Begleitung nach Hause gehen.","Lösung für die Mundhöhle (Buccolam) nur nach ärztlicher Anleitung anwenden, danach die Atmung beobachten und bei anhaltendem Krampfanfall den Notruf 144 wählen.","Keinen Alkohol trinken; Grapefruitsaft erhöht bei Einnahme den Midazolam-Spiegel.","Nach längerer Anwendung schrittweise absetzen (Entzugssymptome)."],"darreichung":["Filmtabletten","Injektionslösung","Lösung zur Anwendung in der Mundhöhle (Fertigspritze)"]},"midodrin":{"wirkmechanismus":"Hebt den Blutdruck, indem es die Blutgefässe verengt. Midodrin ist eine Vorstufe (Prodrug), die im Körper in den wirksamen Metaboliten Desglymidodrin umgewandelt wird. Dieser stimuliert Alpha-1-Rezeptoren in Arterien und Venen; der Gefässwiderstand steigt, und das Blut versackt beim Aufstehen weniger in den Beinen. Desglymidodrin gelangt kaum ins Gehirn und wirkt nicht direkt auf das Herz.","nebenwirkungen":{"sehrHaeufig":["Gänsehaut (Piloerektion)","Juckreiz, besonders an der Kopfhaut","Kribbeln (Parästhesien), besonders an der Kopfhaut"],"haeufig":["Blutdruckanstieg im Liegen (Supine-Hypertonie)","Kopfschmerzen","Frösteln, Hitzewallungen","Hautausschlag","Übelkeit, Verdauungsbeschwerden, Mundschleimhautentzündung","Harndrang, Harnverhalt, Schmerzen beim Wasserlassen"],"gelegentlich":["Reflektorische Pulsverlangsamung (Bradykardie)","Herzklopfen","Unruhe, Schlafstörungen, Reizbarkeit"],"selten":["Herzrasen (Tachykardie)","Erhöhte Leberwerte"]},"schwangerschaft":"Keine ausreichenden Daten, in Tierstudien schädliche Wirkungen; in der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Midodrin in die Muttermilch übergeht; in der Stillzeit nicht anwenden.","hinweise":["Die letzte Tagesdosis mindestens 4 Stunden vor dem Schlafengehen einnehmen und nicht flach liegen (Blutdruckanstieg im Liegen).","Blutdruck regelmässig im Liegen und im Stehen messen; bei Herzklopfen, starkem Kopfschmerz oder verschwommenem Sehen ärztlich melden.","Nieren- und Leberwerte werden vor und während der Behandlung kontrolliert."],"darreichung":["Tabletten"]},"midostaurin":{"wirkmechanismus":"Bremst die Vermehrung bösartiger Blutzellen, deren Wachstum durch veränderte Enzyme angetrieben wird. Midostaurin hemmt mehrere Tyrosinkinasen, darunter mutiertes und unverändertes FLT3 (ITD- und TKD-Mutationen) sowie KIT einschliesslich der für Mastozytose typischen D816V-Mutation, daneben PDGFR und VEGFR-2. Dadurch werden Signale für Zellteilung und Überleben unterbrochen und der programmierte Zelltod ausgelöst. Auch die beiden Hauptmetaboliten (CGP62221, CGP52421) sind wirksam.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen, Durchfall, Verstopfung","Infektionen (Atemwege, Harnwege, Katheter); Fieber bei Neutropenie (bei AML)","Blutarmut, Mangel an weissen Blutkörperchen und Blutplättchen","Kopfschmerzen, Schlaflosigkeit, Schwindel","Nasenbluten, Atemnot, Pleuraerguss (Wasser im Brustfellraum)","Hyperglykämie (erhöhter Blutzucker), erhöhte Leber- und Pankreaswerte","Periphere Ödeme, Müdigkeit, Fieber, Gelenk- und Rückenschmerzen","Schuppende Hautentzündung, Schwitzen, punktförmige Hautblutungen"],"haeufig":["QT-Verlängerung im EKG","Herzinsuffizienz, Perikarderguss (Herzbeutelerguss)","Sepsis, Lungenentzündung","Zittern, Ohnmacht (Synkope)","Pneumonitis (Lungenentzündung ohne Erreger)","Magen-Darm-Blutungen"],"unbekannt":["Interstitielle Lungenerkrankung, akutes Atemnotsyndrom (ARDS)","Abnahme der Herzpumpfunktion (Auswurffraktion)","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nicht anwenden, ausser bei zwingender Notwendigkeit. Frauen müssen während der Behandlung und mindestens 4 Monate danach hochwirksam verhüten.","stillzeit":"Während der Behandlung und mindestens 4 Monate danach nicht stillen.","hinweise":["Zweimal täglich mit einer Mahlzeit einnehmen; Kapseln unzerkaut schlucken, nicht öffnen oder zerdrücken.","Gegen Übelkeit und Erbrechen werden meist vorbeugend Mittel gegeben.","Blutbild, EKG und Lunge werden überwacht; neuen Husten, Atemnot oder Fieber sofort melden.","Kein Johanniskraut und keine Grapefruit; andere Medikamente nur nach Rücksprache."],"darreichung":["Weichkapseln"]},"mifamurtid":{"wirkmechanismus":"Regt Fresszellen des Immunsystems an, verbliebene Krebszellen zu zerstören. Mifamurtid ist ein synthetischer Abkömmling von Muramyldipeptid, dem kleinsten immunstimulierenden Bestandteil der Zellwand von Mykobakterien, und in Liposomen verpackt. Es bindet an den Rezeptor NOD2 von Monozyten und Makrophagen und aktiviert diese, wodurch Botenstoffe wie TNF-alpha, Interleukin-1 und Interleukin-6 freigesetzt werden. Die Liposomen werden vor allem von Makrophagen in Lunge, Leber und Milz aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Fieber, Schüttelfrost, meist einige Stunden nach der Infusion","Müdigkeit, Schwäche, Unwohlsein, Unterkühlung (Hypothermie)","Kopfschmerzen, Schwindel","Herzrasen (Tachykardie), Blutdruckanstieg oder -abfall","Atemnot, schnelle Atmung, Husten","Übelkeit, Erbrechen, Durchfall, Verstopfung, Bauchschmerzen, Appetitlosigkeit","Muskel-, Gelenk-, Rücken-, Glieder- und Brustschmerzen","Anämie (Blutarmut), starkes Schwitzen"],"haeufig":["Infektionen bis Sepsis","Neutropenie, Thrombozytopenie (Mangel an Blutplättchen)","Hörverlust, Ohrensausen (Tinnitus)","Hautausschlag, Juckreiz"],"unbekannt":["Pleura- und Perikarderguss (Flüssigkeit um Lunge oder Herz)","Bronchospasmus bei Asthma","Venenthrombose, Gefässentzündung","Schwere allergische Reaktionen"]},"schwangerschaft":"Nicht anwenden; Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Fieber und Schüttelfrost treten oft einige Stunden nach der Infusion auf; zur Fiebersenkung nur das ärztlich empfohlene Mittel (z. B. Paracetamol) verwenden – hoch dosierte NSAR schwächen die Wirkung.","Regelmässige Hörtests während der Behandlung.","Atemnot oder Engegefühl in der Brust sofort melden."],"darreichung":["Pulver zur Herstellung einer liposomalen Infusionssuspension"]},"mifepriston":{"wirkmechanismus":"Hebt die Wirkung des Schwangerschaftshormons Progesteron auf, sodass sich die Schwangerschaft nicht halten kann. Mifepriston ist ein synthetisches Steroid, das den Progesteronrezeptor kompetitiv blockiert (in höherer Dosis auch den Glukokortikoidrezeptor). Dadurch löst sich die Gebärmutterschleimhaut ab, der Gebärmutterhals wird weich und öffnet sich, und die Gebärmutter wird für die Wirkung von Prostaglandinen empfindlicher. Das anschliessend gegebene Prostaglandin löst die Ausstossung aus.","nebenwirkungen":{"sehrHaeufig":["Gebärmutterkrämpfe, Unterleibsschmerzen (v. a. nach dem Prostaglandin)","Übelkeit, Erbrechen, Durchfall (v. a. durch das Prostaglandin)"],"haeufig":["Starke Blutungen (selten Ausschabung oder Transfusion nötig)","Infektion nach dem Abbruch, z. B. Gebärmutterentzündung","Leichte bis mässige Magen-Darm-Krämpfe"],"gelegentlich":["Blutdruckabfall","Hautausschlag (Überempfindlichkeit)"],"selten":["Kopfschmerzen","Unwohlsein, Hitzewallungen, Schwindel, Schüttelfrost, Fieber","Gebärmutterriss (v. a. bei Abbruch nach dem ersten Drittel mit Prostaglandin)","Nesselsucht, Hautrötung"],"sehrSelten":["Schwerer, teils tödlicher septischer oder toxischer Schock"],"unbekannt":["Schwere Hautreaktionen (z. B. toxische epidermale Nekrolyse)","Angioödem (Schwellung von Gesicht und Rachen)"]},"schwangerschaft":"Wird zum Abbruch einer bestehenden Schwangerschaft eingesetzt. Bleibt die Schwangerschaft nach erfolgloser Behandlung bestehen, besteht ein Fehlbildungsrisiko (v. a. durch das Prostaglandin); die Nachkontrolle ist deshalb zwingend.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; ob weitergestillt werden kann, mit der Ärztin oder dem Arzt besprechen.","hinweise":["Anwendung nur in dafür eingerichteten Praxen oder Spitälern; Kontrolluntersuchung nach 14–21 Tagen ist zwingend.","Eine Blutung beweist nicht, dass der Abbruch vollständig ist.","Bei sehr starker oder lang anhaltender Blutung, Fieber oder starken Schmerzen sofort ärztliche Hilfe suchen.","Ein neuer Eisprung ist schon wenige Tage nach dem Abbruch möglich – Verhütung frühzeitig besprechen."],"darreichung":["Tabletten"]},"migalastat":{"wirkmechanismus":"Hilft einem fehlerhaft gefalteten, aber noch funktionsfähigen Enzym, an seinen Wirkort in der Zelle zu gelangen. Migalastat bindet bei bestimmten ansprechenden Mutationen an das aktive Zentrum der Alpha-Galaktosidase A und stabilisiert das Enzym. So wird es in die Lysosomen transportiert, wo sich Migalastat wieder löst und das Enzym Globotriaosylceramid (Gb3) abbauen kann. Bei nicht ansprechenden Mutationen ist Migalastat unwirksam.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Depression","Parästhesien (Kribbeln), Schwindel, Drehschwindel","Palpitationen (Herzklopfen), Atemnot, Nasenbluten","Durchfall, Übelkeit, Bauchschmerzen, Verstopfung, Mundtrockenheit","Hautausschlag, Juckreiz","Muskelkrämpfe, Muskelschmerzen, Gliederschmerzen","Eiweiss im Urin (Proteinurie)","Müdigkeit, Gewichtszunahme, erhöhte CK im Blut"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Nicht bekannt, ob Migalastat in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Jeden zweiten Tag zur gleichen Zeit einnehmen, nie an zwei aufeinanderfolgenden Tagen.","2 Stunden vor und 2 Stunden nach der Einnahme nichts essen und keine koffeinhaltigen Getränke trinken; Wasser ist erlaubt.","Eine vergessene Dosis nur innerhalb von 12 Stunden nachholen."],"darreichung":["Hartkapseln"]},"miglustat":{"wirkmechanismus":"Vermindert die Bildung von Fettstoffen, die sich bei diesen Speicherkrankheiten in den Zellen anhäufen. Miglustat hemmt die Glucosylceramid-Synthase, das erste Enzym der Glykosphingolipid-Bildung. Dadurch fällt weniger Glucosylceramid an, das der Körper wegen eines Enzymdefekts nicht ausreichend abbauen kann (Substratreduktion). Miglustat gelangt ins Gehirn und kann so auch neurologische Krankheitszeichen bei Niemann-Pick Typ C beeinflussen.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Blähungen","Bauchschmerzen","Gewichtsabnahme","Tremor (Zittern)"],"haeufig":["Appetitminderung","Übelkeit, Erbrechen, Verstopfung, Verdauungsbeschwerden","Kopfschmerzen, Schwindel","Parästhesien (Kribbeln) und periphere Neuropathie","Gedächtnis- und Koordinationsstörungen","Depression, Schlafstörungen, verminderte Libido","Muskelkrämpfe, Muskelschwäche, Müdigkeit","Thrombozytopenie (Mangel an Blutplättchen)"]},"schwangerschaft":"Nicht anwenden. Frauen im gebärfähigen Alter verhüten wirksam; Männer verhüten während und bis 3 Monate nach der Behandlung.","stillzeit":"Nicht anwenden.","hinweise":["Eine Ernährung mit wenig Haushaltszucker (Saccharose) und Milchzucker kann Durchfall und Blähungen vermindern.","Kribbeln oder Taubheitsgefühle an Händen und Füssen ärztlich melden.","Regelmässige neurologische Kontrollen."],"darreichung":["Hartkapseln"]},"milrinon":{"wirkmechanismus":"Stärkt die Pumpkraft des Herzens und erweitert gleichzeitig die Blutgefässe. Milrinon hemmt das Enzym Phosphodiesterase 3 in Herzmuskel- und Gefässmuskelzellen, wodurch das zyklische AMP (cAMP) ansteigt. Im Herzen nimmt dadurch die Kontraktionskraft zu, in den Gefässen erschlafft die Muskulatur, sodass Vor- und Nachlast sinken. Die Wirkung ist unabhängig von Beta-Rezeptoren und bleibt daher auch unter Betablockern erhalten.","nebenwirkungen":{"haeufig":["Ventrikuläre Extrasystolen und Kammertachykardien","Supraventrikuläre Rhythmusstörungen","Hypotonie (Blutdruckabfall)","Kopfschmerzen"],"gelegentlich":["Kammerflimmern","Brustschmerzen (Angina pectoris)","Zittern (Tremor)","Thrombozytopenie (Mangel an Blutplättchen)","Hypokaliämie (Kaliummangel)","Erhöhte Leberwerte"],"sehrSelten":["Torsade de pointes (gefährliche Rhythmusstörung)","Anaphylaktischer Schock","Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Nierenversagen als Folge eines Blutdruckabfalls","Reaktionen an der Infusionsstelle"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Nicht bekannt, ob Milrinon in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital als Infusion unter laufender Überwachung von EKG, Blutdruck, Flüssigkeitsbilanz, Elektrolyten und Nierenfunktion gegeben.","Nicht mit Furosemid oder Bumetanid über dieselbe Leitung infundieren."],"darreichung":["Injektionslösung bzw. Konzentrat zur Herstellung einer Infusionslösung"]},"minocyclin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien. Minocyclin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und blockiert die Anlagerung der Transfer-RNA, sodass die Bakterien keine Eiweisse mehr bilden können (bakteriostatisch). Es ist stärker fettlöslich als ältere Tetracycline, wird gut aufgenommen und dringt gut in Haut, Talgdrüsen und das Nervensystem ein – daher wirkt es bei Akne, verursacht aber auch häufiger Schwindel.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit"],"selten":["Drehschwindel (Vertigo), Kopfschmerzen, Kribbeln","Akutes Nierenversagen, interstitielle Nephritis (Nierenentzündung)","Übelkeit, Erbrechen, Durchfall","Lichtempfindlichkeit, Hautausschlag, Juckreiz","Verfärbung von Haut, Nägeln und Zähnen (Hyperpigmentierung)","Leberentzündung, erhöhte Leberwerte","Lupus-ähnliches Syndrom mit Gelenk- und Muskelschmerzen","Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie)"],"sehrSelten":["Autoimmune Leberentzündung, Leberversagen","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautablösung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung)","Erhöhter Hirndruck (Pseudotumor cerebri)","Pseudomembranöse Kolitis (schwere Darmentzündung)","Agranulozytose, hämolytische Anämie"]},"schwangerschaft":"Kontraindiziert: Tetracycline können beim Ungeborenen bleibende Zahnverfärbungen und Störungen des Knochenwachstums verursachen.","stillzeit":"Kontraindiziert: Minocyclin geht in die Muttermilch über.","hinweise":["Mit einem grossen Glas Wasser in aufrechter Haltung einnehmen, nicht direkt vor dem Schlafengehen.","Antazida, Eisen-, Calcium-, Magnesium- und Zinkpräparate mit 2–3 Stunden Abstand einnehmen.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen.","Hautausschlag mit Fieber, Gelbsucht, Gelenkschmerzen oder anhaltende Kopfschmerzen sofort ärztlich melden; bei längerer Behandlung Leberwerte kontrollieren."],"darreichung":["Kapseln"]},"minoxidil":{"wirkmechanismus":"Erweitert die kleinen Arterien und senkt so den Blutdruck; auf der Kopfhaut regt es das Haarwachstum an. Minoxidil wird zu Minoxidilsulfat umgewandelt, das ATP-abhängige Kaliumkanäle der glatten Gefässmuskulatur öffnet und diese erschlaffen lässt. Die starke Gefässerweiterung führt reflektorisch zu schnellerem Puls sowie zu Salz- und Wassereinlagerung, weshalb die Tabletten immer mit einem Betablocker und einem Diuretikum kombiniert werden. Auf der Kopfhaut verlängert Minoxidil die Wachstumsphase der Haarfollikel und vergrössert verkleinerte Follikel; der genaue Mechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (Lösung, Schaum)","Hypertrichose (vermehrter Haarwuchs an Gesicht und Körper) unter Tabletten","EKG-Veränderungen (T-Wellen) unter Tabletten"],"haeufig":["Juckreiz, Rötung und Schuppung der Kopfhaut","Hautausschlag, Kontaktdermatitis, akneartige Hautentzündung","Unerwünschter Haarwuchs ausserhalb der Kopfhaut, z. B. im Gesicht bei Frauen (Lösung, Schaum)","Salz- und Wassereinlagerung mit Ödemen und Gewichtszunahme (Tabletten)","Perikarderguss (Herzbeutelerguss), selten bis zur lebensbedrohlichen Herzbeuteltamponade (Tabletten)"],"gelegentlich":["Schwindel","Übelkeit"],"selten":["Herzklopfen, Herzrasen, Brustschmerzen (Lösung, Schaum)","Thrombozytopenie und Leukopenie (Mangel an Blutplättchen und weissen Blutkörperchen) unter Tabletten","Schwere Hautreaktionen (Stevens-Johnson-Syndrom) unter Tabletten"],"unbekannt":["Vorübergehend verstärkter Haarausfall zu Beginn der Behandlung","Veränderungen von Haarfarbe oder Haarstruktur","Blutdruckabfall","Augenreizung","Allergische Reaktionen bis zum Angioödem","Atemnot, geschwollene Hände oder Füsse (Lösung, Schaum – Anwendung beenden)","Reflextachykardie (Herzrasen) unter Tabletten ohne Betablocker","Brustspannen (Tabletten)"]},"schwangerschaft":"Lösung und Schaum: in der Schwangerschaft nicht anwenden. Tabletten nur bei zwingender Notwendigkeit; bei Neugeborenen wurde vermehrter Haarwuchs beobachtet.","stillzeit":"Minoxidil geht in die Muttermilch über; während der Stillzeit nicht anwenden.","hinweise":["Lösung oder Schaum nur auf die trockene, gesunde Kopfhaut auftragen und danach die Hände waschen; eine Wirkung zeigt sich frühestens nach 2–4 Monaten.","Nach dem Absetzen fallen die neu gewachsenen Haare innerhalb von etwa 3–4 Monaten wieder aus.","Bei Brustschmerzen, Herzrasen, Schwindel, Ohnmacht, plötzlicher Gewichtszunahme oder geschwollenen Händen und Füssen die Anwendung beenden und ärztlichen Rat einholen.","Tabletten: immer zusammen mit dem verordneten Betablocker und Diuretikum einnehmen und das Körpergewicht regelmässig kontrollieren."],"darreichung":["Lösung zur Anwendung auf der Kopfhaut","Schaum zur Anwendung auf der Kopfhaut","Tabletten"]},"mirabegron":{"wirkmechanismus":"Entspannt den Blasenmuskel während der Füllungsphase, sodass die Blase mehr Urin speichern kann und der Harndrang seltener auftritt. Mirabegron ist ein selektiver Agonist am Beta-3-Adrenozeptor, der im Blasenmuskel (Detrusor) die glatte Muskulatur über einen Anstieg von cAMP relaxiert. Die Entleerung der Blase beim Wasserlassen wird dabei nicht beeinträchtigt. Da keine Muskarinrezeptoren blockiert werden, fehlen Mundtrockenheit und Verstopfung weitgehend.","nebenwirkungen":{"haeufig":["Harnwegsinfektion","Herzrasen (Tachykardie)","Übelkeit","Verstopfung","Durchfall","Kopfschmerzen","Schwindel"],"gelegentlich":["Scheideninfektion, Blasenentzündung","Herzklopfen, Vorhofflimmern","Verdauungsbeschwerden, Gastritis","Nesselsucht, Hautausschlag, Juckreiz","Gelenkschwellung","Juckreiz im Genitalbereich","Blutdruckanstieg","Anstieg der Leberwerte (GGT, AST, ALT)"],"selten":["Schwellung von Augenlidern oder Lippen, Angioödem","Leukozytoklastische Vaskulitis (Entzündung kleiner Hautgefässe), Purpura","Harnverhalt"],"sehrSelten":["Hypertensive Krise (gefährlich hoher Blutdruck)"],"unbekannt":["Schlaflosigkeit","Verwirrtheit"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung verhüten.","stillzeit":"Nicht anwenden – im Tierversuch ging Mirabegron in die Milch über.","hinweise":["Blutdruck regelmässig kontrollieren, besonders bei bekanntem Bluthochdruck.","Retardtablette einmal täglich ganz mit Flüssigkeit schlucken, nicht teilen, zerkauen oder zerdrücken.","Die volle Wirkung zeigt sich oft erst nach einigen Wochen."],"darreichung":["Retardtabletten"]},"mirdametinib":{"wirkmechanismus":"Lässt die bei Neurofibromatose wachsenden Nerventumoren schrumpfen oder bremst ihr Wachstum. Bei Neurofibromatose Typ 1 fehlt das Eiweiss Neurofibromin, wodurch der RAS–RAF–MEK–ERK-Signalweg dauerhaft aktiv ist. Mirdametinib hemmt die Kinasen MEK1 und MEK2 allosterisch und unterbricht damit diesen Wachstumsreiz.","nebenwirkungen":{"sehrHaeufig":["Akneartige Hautentzündung, Hautausschlag, trockene Haut","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Müdigkeit","Muskel- und Skelettschmerzen","Paronychie (Nagelbettentzündung)","Erhöhte CK-Werte","Abnahme der Herzleistung (verminderte Auswurffraktion), vor allem bei Kindern"],"haeufig":["Verschwommenes Sehen"],"unbekannt":["Netzhautvenenverschluss","Seröse Netzhautablösung (Ablösung des retinalen Pigmentepithels)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Während und nach der Behandlung zuverlässig verhüten (Dauer gemäss Fachinformation).","stillzeit":"Während der Behandlung und kurz danach nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen; Einnahme 3 Wochen, dann 1 Woche Pause.","Sehstörungen, Atemnot oder Beinschwellungen umgehend ärztlich melden.","Regelmässige Kontrollen: Augen, Herzfunktion (Ultraschall) und Haut."],"darreichung":["Hartkapseln","Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"mirikizumab":{"wirkmechanismus":"Beruhigt die Entzündung der Darmschleimhaut, indem es einen zentralen Entzündungsbotenstoff ausschaltet. Mirikizumab ist ein humanisierter monoklonaler IgG4-Antikörper, der an die p19-Untereinheit von Interleukin-23 bindet und so dessen Bindung an den IL-23-Rezeptor verhindert. Dadurch werden die IL-23-abhängige Aktivierung von Th17-Zellen und die Freisetzung weiterer Entzündungsbotenstoffe gehemmt. Die Behandlung beginnt mit Infusionen und wird mit Spritzen unter die Haut fortgesetzt.","nebenwirkungen":{"haeufig":["Infektionen der oberen Atemwege","Kopfschmerzen","Hautausschlag","Gelenkschmerzen","Reaktionen an der Einstichstelle"],"gelegentlich":["Gürtelrose (Herpes zoster)","Überempfindlichkeitsreaktionen während der Infusion","Erhöhte Leberwerte (ALT, AST)"],"unbekannt":["Arzneimittelbedingte Leberschädigung"]},"schwangerschaft":"Vorsichtshalber vermeiden. Frauen im gebärfähigen Alter sollen während und mindestens 10 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Mirikizumab in die Muttermilch übergeht; über Stillen oder Behandlung entscheidet die Ärztin oder der Arzt.","hinweise":["Einleitung mit drei Infusionen im Abstand von 4 Wochen, danach alle 4 Wochen Injektion unter die Haut.","Bei Gelbfärbung von Haut oder Augen, dunklem Urin oder Oberbauchschmerzen ärztlich abklären (Leber).","Vor Beginn Tuberkulose-Test; keine Lebendimpfungen während der Behandlung."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung im Fertigpen (unter die Haut)"]},"mirtazapin":{"wirkmechanismus":"Hellt die Stimmung auf, indem es die Freisetzung der Botenstoffe Noradrenalin und Serotonin im Gehirn steigert. Mirtazapin blockiert zentrale präsynaptische Alpha-2-Rezeptoren, die die Ausschüttung dieser Botenstoffe normalerweise bremsen. Gleichzeitig blockiert es die Serotoninrezeptoren 5-HT2 und 5-HT3, sodass vor allem die Wirkung über 5-HT1A-Rezeptoren zum Tragen kommt. Die starke Blockade der Histamin-H1-Rezeptoren erklärt die beruhigende, schlaffördernde und appetitsteigernde Wirkung.","nebenwirkungen":{"sehrHaeufig":["Appetitsteigerung und Gewichtszunahme","Schläfrigkeit, Sedierung (Dämpfung)","Kopfschmerzen","Mundtrockenheit"],"haeufig":["Schwindel, Zittern (Tremor)","Müdigkeit, Lethargie","Abnorme Träume, Verwirrtheit, Angst, Schlaflosigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Übelkeit, Erbrechen, Durchfall, Verstopfung","Hautausschlag (Exanthem)","Gelenk-, Muskel- und Rückenschmerzen","Periphere Ödeme (Wassereinlagerungen)"],"gelegentlich":["Albträume, Halluzinationen, Agitiertheit (Unruhe)","Manie","Akathisie (Bewegungsunruhe), Restless-Legs-Syndrom","Kribbeln (Parästhesien)","Ohnmacht (Synkope), tiefer Blutdruck"],"selten":["Aggressivität","Myoklonien (Muskelzuckungen)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Erhöhte Leberwerte"],"unbekannt":["Agranulozytose und andere Knochenmarkschäden (Fieber, Halsschmerzen)","Hyponatriämie (Natriummangel), SIADH","Suizidgedanken und suizidales Verhalten","Krampfanfälle","Serotoninsyndrom","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","QT-Verlängerung, Torsade de pointes","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (begrenzte Erfahrungen). Wird es bis zur Geburt eingenommen, ist das Neugeborene auf Anpassungsstörungen und Absetzsymptome zu beobachten.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen nur nach ärztlicher Abwägung.","hinweise":["Am besten abends vor dem Schlafengehen einnehmen; Schmelztabletten auf der Zunge zergehen lassen.","Die stimmungsaufhellende Wirkung setzt meist nach 1–2 Wochen ein; nicht abrupt absetzen (Absetzsymptome wie Schwindel, Unruhe, Übelkeit).","Bei Fieber, Halsschmerzen oder Mundgeschwüren sofort ärztlich das Blutbild kontrollieren lassen (seltene Agranulozytose).","Alkohol meiden; Schläfrigkeit kann die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten","Schmelztabletten"]},"mirvetuximab-soravtansin":{"wirkmechanismus":"Bringt ein Zellgift gezielt in Eierstockkrebszellen. Mirvetuximab Soravtansin besteht aus einem Antikörper gegen den Folatrezeptor alpha (FRα), der auf vielen Eierstocktumoren stark vorkommt, und dem daran gekoppelten Maytansinoid DM4. Nach der Aufnahme in die Zelle wird DM4 freigesetzt, hemmt die Mikrotubuli und stoppt die Zellteilung, sodass die Zelle abstirbt; freigesetztes DM4 kann auch benachbarte Tumorzellen schädigen.","nebenwirkungen":{"sehrHaeufig":["Verschwommenes Sehen","Keratopathie (Hornhautveränderungen), trockene Augen","Periphere Neuropathie (Kribbeln, Taubheit)","Müdigkeit","Übelkeit, Durchfall, Bauchschmerzen, Verstopfung","Erhöhte Leberwerte"],"haeufig":["Pneumonitis (Lungenentzündung durch das Medikament)","Lichtempfindlichkeit der Augen, Augenschmerzen, Hornhautentzündung","Katarakt (grauer Star)"]},"schwangerschaft":"Kann das Ungeborene schädigen (enthält ein Zellgift); in der Schwangerschaft nicht anwenden. Frauen im gebärfähigen Alter verhüten während und 7 Monate nach der letzten Dosis.","stillzeit":"Während und 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Augentropfen genau nach Anweisung anwenden; jede Sehstörung sofort melden.","Keine Kontaktlinsen während der Behandlung, ausser auf augenärztliche Anweisung.","Husten, Atemnot oder Fieber sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"misoprostol":{"wirkmechanismus":"Löst Kontraktionen der Gebärmutter aus und öffnet den Gebärmutterhals, sodass die Schwangerschaft ausgestossen wird. Misoprostol ist ein synthetisches Prostaglandin-E1-Analogon und wird rasch in den Wirkmetaboliten Misoprostolsäure umgewandelt. Diese bindet an Prostaglandin-Rezeptoren der Gebärmuttermuskulatur. Mifepriston macht die Gebärmutter zuvor empfindlicher für diese Wirkung. Im Magen hemmt Misoprostol zudem die Säurebildung und schützt die Schleimhaut.","nebenwirkungen":{"sehrHaeufig":["Gebärmutterkrämpfe und Unterleibsschmerzen","Übelkeit, Erbrechen, Durchfall"],"haeufig":["Starke oder verlängerte Blutung","Kopfschmerzen, Schwindel","Fieber, Schüttelfrost (vorübergehend)","Infektion nach dem Abbruch (z. B. Gebärmutterentzündung)"],"gelegentlich":["Hautausschlag","Blutdruckabfall"],"selten":["Schwere Blutung, die eine Ausschabung oder Transfusion erfordert","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Toxisches Schocksyndrom oder schwere, tödlich verlaufende Infektionen (z. B. Clostridium sordellii)"],"unbekannt":["Herzinfarkt, Herzrhythmusstörungen","Gebärmutterriss (v. a. bei Narbe nach Kaiserschnitt, in höheren Schwangerschaftswochen)","Fehlbildungen (z. B. Möbius-Syndrom) bei fortgesetzter Schwangerschaft"]},"schwangerschaft":"Ausschliesslich zur Beendigung der Schwangerschaft. Schreitet die Schwangerschaft trotz Behandlung fort, besteht ein Risiko für Fehlbildungen – Kontrolle nach 2–3 Wochen ist zwingend.","stillzeit":"Misoprostolsäure geht in die Muttermilch über und kann beim Säugling Durchfall auslösen; Stillen nach der Einnahme gemäss ärztlicher Anweisung kurz unterbrechen.","hinweise":["Nur unter ärztlicher Aufsicht und in Kombination mit Mifepriston; die Nachkontrolle nach 14–21 Tagen ist zwingend.","Bei sehr starker Blutung (mehr als 2 dicke Binden pro Stunde über 2 Stunden), Fieber über 38 °C länger als 24 Stunden oder starkem Unwohlsein sofort ärztliche Hilfe holen.","Schmerzmittel wie Ibuprofen dürfen zur Linderung der Krämpfe eingenommen werden."],"darreichung":["Tabletten"]},"mitomycin":{"wirkmechanismus":"Schädigt das Erbgut sich teilender Zellen und bremst so das Tumorwachstum. Mitomycin ist ein aus Streptomyces caespitosus gewonnenes Antibiotikum, das in der Zelle reduktiv aktiviert wird und dann wie ein Alkylans wirkt: Es vernetzt die beiden DNA-Stränge miteinander und hemmt so die DNA-Synthese. Bei der Blasenspülung wirkt es vor allem örtlich auf die Blasenschleimhaut und gelangt nur in geringen Mengen ins Blut.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung mit Mangel an weissen Blutkörperchen und Blutplättchen (bei Infusion, oft verzögert nach Wochen)","Übelkeit und Erbrechen (bei Infusion)"],"haeufig":["Blasenentzündung (Zystitis), auch mit Blut im Urin, schmerzhaftes und häufiges Wasserlösen (bei Blasenspülung)","Hautausschlag, Juckreiz, Kontaktdermatitis, Rötung an Handflächen und Fusssohlen","Interstitielle Pneumonie und Lungenfibrose (Lungengewebsentzündung, -vernarbung), Atemnot, Husten (bei Infusion)","Nierenfunktionsstörung (bei Infusion)"],"gelegentlich":["Haarausfall","Entzündung der Mundschleimhaut","Durchfall, Appetitlosigkeit","Fieber"],"selten":["Lebensbedrohliche Infektionen, Blutvergiftung (Sepsis)","Hämolytisch-urämisches Syndrom (Blutzerfall mit akutem Nierenversagen)","Herzschwäche, besonders nach Vorbehandlung mit Anthrazyklinen","Lungenhochdruck, Verschluss kleiner Lebervenen (veno-okklusive Erkrankung)"],"unbekannt":["Schwere Gewebeschäden (Nekrosen), wenn die Infusion ins Gewebe austritt (Paravasat)","Nach Blasenspülung: Nekrose oder Verkalkung der Blasenwand, Schrumpfblase"]},"schwangerschaft":"Darf in der Schwangerschaft nicht angewendet werden, da Mitomycin erbgut- und fruchtschädigend ist. Frauen und Männer müssen während und nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Regelmässige Blutbildkontrollen; Fieber, Halsschmerzen oder Blutungszeichen sofort melden – die Knochenmarkhemmung kann erst Wochen nach der Gabe auftreten.","Blasenspülung: vorher wenig trinken, die Lösung so lange wie verordnet (meist 1–2 Stunden) in der Blase behalten, danach Hände und Genitalbereich gründlich waschen.","Brennen oder Schmerzen an der Infusionsstelle sofort melden (Gefahr schwerer Gewebeschäden)."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung","Pulver zur Herstellung einer Lösung zur Anwendung in der Harnblase"]},"mitotan":{"wirkmechanismus":"Hemmt die Nebennierenrinde, sodass weniger Kortisol und andere Nebennierenhormone gebildet werden, und schädigt die Tumorzellen der Nebennierenrinde. Mitotan (o,p'-DDD) wird in den Mitochondrien der Nebennierenrindenzellen zu reaktiven Metaboliten umgewandelt, die diese Zellen zerstören (adrenolytische Wirkung). Zusätzlich hemmt es Enzyme der Steroidhormonbildung, u. a. die Cholesterin-Seitenkettenspaltung und die 11-beta-Hydroxylase. Der Wirkstoff reichert sich im Fettgewebe an und wird nur sehr langsam ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Nebenniereninsuffizienz (Kortisolmangel)","Übelkeit, Erbrechen, Durchfall, Oberbauchbeschwerden, Schleimhautentzündung","Appetitlosigkeit","Schläfrigkeit, Müdigkeit, Schwindel, Gangunsicherheit (Ataxie), Missempfindungen","Verwirrtheit, Muskelschwäche","Erhöhte Leberwerte und erhöhte Blutfette (Cholesterin, Triglyceride)","Hautausschlag","Leukopenie (Mangel an weissen Blutkörperchen); Gynäkomastie (Brustvergrösserung beim Mann)"],"haeufig":["Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen)","Verlängerte Blutungszeit","Polyneuropathie (Nervenschädigung), Bewegungsstörungen","Kopfschmerzen","Beeinträchtigung der geistigen Leistungsfähigkeit"],"unbekannt":["Sehstörungen (Doppeltsehen, Linsentrübung, Netzhautschäden)","Autoimmunhepatitis (Leberentzündung)","Bluthochdruck, Blutdruckabfall beim Aufstehen","Hämorrhagische Zystitis (blutige Blasenentzündung), Blut oder Eiweiss im Urin","Eierstockzysten","Opportunistische Pilzinfektionen","Fieber, Geschmacksstörungen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit (kaum Erfahrungen; Schädigung der kindlichen Nebenniere möglich). Frauen im gebärfähigen Alter müssen während und nach der Behandlung zuverlässig verhüten, solange Mitotan im Blut nachweisbar ist.","stillzeit":"Kontraindiziert: Mitotan geht in die Muttermilch über. Während der Behandlung und solange der Wirkstoff im Blut nachweisbar ist, nicht stillen.","hinweise":["Zu Mahlzeiten mit fettreichen Speisen einnehmen (bessere Aufnahme).","Mitotan-Blutspiegel werden regelmässig kontrolliert; bei Spiegeln über 20 mg/l nehmen Nebenwirkungen am Nervensystem deutlich zu.","Notfallausweis für Nebenniereninsuffizienz mitführen; bei Infekt, Unfall oder Operation sofort die Ärztin oder den Arzt informieren.","Schläfrigkeit und Schwindel können die Fahrtüchtigkeit beeinträchtigen; der Wirkstoff bleibt nach dem Absetzen noch Monate im Körper."],"darreichung":["Tabletten"]},"mitoxantron":{"wirkmechanismus":"Schädigt die Erbsubstanz von Krebszellen und hemmt deren Teilung. Mitoxantron lagert sich zwischen die DNA-Basenpaare ein und hemmt die Topoisomerase II, wodurch DNA-Strangbrüche entstehen; es wirkt in allen Phasen des Zellzyklus. Zusätzlich hemmt es die Vermehrung von B- und T-Lymphozyten und Makrophagen und wirkt dadurch immunsuppressiv.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Knochenmarkhemmung mit Leukopenie, Neutropenie und Anämie","Übelkeit, Erbrechen","Haarausfall"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Mundschleimhautentzündung, Durchfall, Verstopfung, Bauchschmerzen, Appetitlosigkeit","Herzinsuffizienz, Abnahme der Pumpfunktion, Herzrhythmusstörungen","Müdigkeit, Schwäche, Fieber","Atemnot","Ausbleiben der Regelblutung"],"gelegentlich":["Sekundäre akute myeloische Leukämie, myelodysplastisches Syndrom"],"unbekannt":["Blaugrüne Verfärbung des Urins für 1–2 Tage, selten auch von Augenweiss, Haut oder Nägeln","Leberschädigung","Anaphylaxie (schwere allergische Reaktion)","Gewebeschäden bei Paravasat"]},"schwangerschaft":"Nicht anwenden; Mitoxantron kann das Ungeborene schädigen. Frauen und Männer müssen während der Behandlung und mehrere Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert; Mitoxantron geht in die Muttermilch über.","hinweise":["Der Urin kann sich 1–2 Tage blaugrün färben, selten auch Augenweiss oder Nägel – das ist harmlos.","Herzfunktion und Blutbild werden regelmässig kontrolliert; Atemnot, Herzklopfen oder geschwollene Beine melden.","Schmerzen oder Brennen an der Infusionsstelle sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"mivacurium":{"wirkmechanismus":"Erschlafft die Skelettmuskulatur für kurze Eingriffe. Mivacurium blockiert kompetitiv die nikotinischen Acetylcholinrezeptoren an der motorischen Endplatte (nicht depolarisierend). Es wird wie Suxamethonium durch die Plasmacholinesterase abgebaut und wirkt daher nur kurz, etwa 15–20 Minuten. Bei einem Mangel an Plasmacholinesterase ist die Wirkung stark verlängert.","nebenwirkungen":{"sehrHaeufig":["Hautrötung (Flush) durch Histaminfreisetzung"],"haeufig":["Blutdruckabfall"],"gelegentlich":["Tachykardie (Herzrasen)","Bronchospasmus (Verkrampfung der Atemwege)","Hautausschlag, Rötung, Nesselsucht"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; die Plasmacholinesterase ist in der Schwangerschaft vermindert, die Wirkung kann daher verlängert sein.","stillzeit":"Nicht bekannt, ob der Wirkstoff in die Muttermilch übergeht; wegen der sehr kurzen Wirkdauer ist ein Risiko unwahrscheinlich.","hinweise":["Wird nur von Anästhesie-Fachpersonen mit Beatmungsmöglichkeit angewendet.","Vor einer Narkose einen bekannten Cholinesterase-Mangel oder ungewöhnlich lange Narkosewirkung (auch in der Familie) angeben.","Allergien gegen Muskelrelaxanzien vor einer Operation angeben."],"darreichung":["Injektionslösung"]},"moclobemid":{"wirkmechanismus":"Hebt die Stimmung, indem es den Abbau der Botenstoffe Serotonin, Noradrenalin und Dopamin im Gehirn verlangsamt. Moclobemid hemmt das Enzym Monoaminoxidase A selektiv und reversibel; die Hemmung klingt innerhalb von etwa 24 Stunden nach dem Absetzen ab. Da Tyramin aus der Nahrung das Medikament vom Enzym verdrängen kann, sind – anders als bei älteren, irreversiblen MAO-Hemmern – keine strengen Diätvorschriften nötig. Abbau in der Leber v. a. über CYP2C19 und CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Schlafstörungen","Schwindel","Kopfschmerzen","Mundtrockenheit","Übelkeit"],"haeufig":["Unruhe, Angst, Reizbarkeit","Missempfindungen (Parästhesien)","Sehstörungen","Blutdruckabfall (Hypotonie)","Erbrechen, Durchfall, Verstopfung","Hautausschlag"],"gelegentlich":["Verwirrtheit","Suizidgedanken","Geschmacksstörungen","Wassereinlagerungen (Ödeme)","Juckreiz, Nesselsucht","Hitzegefühl (Flush)","Schwäche"],"unbekannt":["Serotoninsyndrom (bei Kombination mit serotonergen Mitteln)","Hyponatriämie (Natriummangel)","Erhöhte Leberwerte","Milchfluss (Galaktorrhö)","Appetitminderung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung (keine ausreichenden Erfahrungen).","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nach dem Essen einnehmen; sehr grosse Mengen tyraminreicher Nahrungsmittel meiden.","Keine rezeptfreien Schnupfen-, Grippe- oder Hustenmittel (Pseudoephedrin, Phenylephrin, Dextromethorphan) ohne Rücksprache mit Apotheke oder Arztpraxis.","Beim Wechsel auf oder von anderen Antidepressiva die ärztlich vorgegebenen Pausen einhalten.","Die stimmungsaufhellende Wirkung setzt meist nach 1–3 Wochen ein."],"darreichung":["Filmtabletten"]},"modafinil":{"wirkmechanismus":"Fördert die Wachheit, ohne so stark anzuregen wie klassische Aufputschmittel. Modafinil hemmt den Dopamin-Transporter und erhöht so die Dopaminkonzentration in bestimmten Hirnregionen; zusätzlich werden wachheitsfördernde Systeme mit Noradrenalin, Histamin und Orexin aktiviert. Der genaue Wirkmechanismus ist nicht vollständig geklärt. Modafinil induziert das Enzym CYP3A4 (vor allem im Darm) und hemmt CYP2C19.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Nervosität, Schlaflosigkeit, Angst, Reizbarkeit","Depression, Denkstörungen, Verwirrtheit","Schwindel, Schläfrigkeit, Missempfindungen","Verschwommenes Sehen","Herzrasen, Herzklopfen, Hitzegefühl (Gefässerweiterung)","Bauchschmerzen, Übelkeit, Mundtrockenheit, Durchfall, Verdauungsbeschwerden, Verstopfung","Appetitminderung","Brustschmerzen, Schwäche, veränderte Leberwerte"],"gelegentlich":["Bluthochdruck, Herzrhythmusstörungen (z. B. Extrasystolen)","Allergische Reaktionen, Hautausschlag, Akne, Juckreiz","Unruhe, Libidominderung, Albträume","Atemnot","Muskelzuckungen, Bewegungsstörungen","Gewichtsveränderungen"],"selten":["Halluzinationen, Manie, Psychose"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS (schwere Haut- und Überempfindlichkeitsreaktionen)","Angioödem, Anaphylaxie (schwere allergische Reaktion)","Suizidgedanken","Wahnvorstellungen, Aggressivität"]},"schwangerschaft":"Nicht anwenden: Hinweise auf ein erhöhtes Fehlbildungsrisiko. Frauen im gebärfähigen Alter müssen während der Behandlung und bis 2 Monate danach zuverlässig – nicht allein hormonell – verhüten.","stillzeit":"Nicht anwenden (keine ausreichenden Daten).","hinweise":["Morgens einnehmen (gegebenenfalls zweite Dosis am Mittag), damit der Nachtschlaf nicht gestört wird.","Bei Hautausschlag, Fieber oder Schleimhautblasen sofort absetzen und ärztlich abklären lassen (schwere Hautreaktionen).","Blutdruck und Puls regelmässig kontrollieren.","Ersetzt keinen ausreichenden Schlaf; die Fahrtüchtigkeit ärztlich beurteilen lassen."],"darreichung":["Tabletten"]},"molsidomin":{"wirkmechanismus":"Erweitert die Blutgefässe und entlastet so das Herz, das dadurch weniger Sauerstoff braucht. Molsidomin ist ein Prodrug: In der Leber entsteht daraus Linsidomin (SIN-1), das ohne Beteiligung von Enzymen Stickstoffmonoxid (NO) freisetzt. NO aktiviert in der glatten Gefässmuskulatur die lösliche Guanylatcyclase; der Anstieg von cGMP erschlafft vor allem die Venen (Senkung der Vorlast) und erweitert auch die Herzkranzgefässe. Anders als bei Nitraten entwickelt sich kaum eine Gewöhnung (Toleranz).","nebenwirkungen":{"haeufig":["Kopfschmerzen, vor allem zu Behandlungsbeginn","Hypotonie (tiefer Blutdruck), Schwindel und Kreislaufbeschwerden beim Aufstehen"],"selten":["Übelkeit","Allergische Hautreaktionen (Ausschlag, Juckreiz)"],"sehrSelten":["Anaphylaktischer Schock (schwere allergische Reaktion)","Bronchospasmus (Verkrampfung der Atemwege)","Thrombozytopenie (Mangel an Blutplättchen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Im ersten Drittel nicht anwenden, danach nur bei zwingender Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Nicht zur Behandlung eines akuten Angina-pectoris-Anfalls geeignet – dafür ein rasch wirkendes Nitrat (z. B. Nitroglycerin-Spray) verwenden.","Keine Potenzmittel vom Typ Sildenafil oder Tadalafil einnehmen: lebensgefährlicher Blutdruckabfall.","Alkohol verstärkt die Blutdrucksenkung; besonders zu Beginn kann die Fahrtüchtigkeit beeinträchtigt sein.","Retardtabletten unzerkaut mit Flüssigkeit einnehmen."],"darreichung":["Tabletten","Retardtabletten"]},"momelotinib":{"wirkmechanismus":"Verkleinert die Milz, lindert Beschwerden der Myelofibrose und kann die Blutarmut bessern. Momelotinib hemmt die Januskinasen JAK1 und JAK2 und bremst so die überaktive JAK-STAT-Signalübertragung. Zusätzlich hemmt es den Activin-Rezeptor ACVR1 (ALK2); dadurch sinkt das Eisen-Regulationshormon Hepcidin, mehr Eisen wird für die Blutbildung verfügbar.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Durchfall, Übelkeit","Müdigkeit, Schwäche"],"haeufig":["Infektionen (Harnwege, obere Atemwege, Lungenentzündung)","Neutropenie (Mangel an weissen Blutkörperchen)","Bauchschmerzen, Erbrechen, Verstopfung","Schwindel, Kopfschmerzen, periphere Neuropathie (Kribbeln, Taubheit)","Husten","Juckreiz","Erhöhte Leberwerte","Gelenk- und Gliederschmerzen, Fieber"],"unbekannt":["Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und bis mindestens 1 Woche nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert; während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich einnehmen, mit oder ohne Essen.","Fieber, Husten, Brennen beim Wasserlösen oder Gürtelrose-Anzeichen umgehend ärztlich melden.","Regelmässige Kontrollen: Blutbild und Leberwerte."],"darreichung":["Filmtabletten"]},"mometason":{"wirkmechanismus":"Hemmt örtlich Entzündung, Schwellung und Juckreiz. Mometasonfuroat ist ein stark wirksames synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor bindet und die Bildung von Entzündungsbotenstoffen sowie das Einwandern von Entzündungszellen unterdrückt. Es wirkt vor allem dort, wo es aufgetragen, gesprüht oder inhaliert wird: Verschluckter oder aufgenommener Wirkstoff wird in der Leber über CYP3A4 rasch abgebaut, sodass der übrige Körper wenig belastet wird.","nebenwirkungen":{"haeufig":["Nasenbluten, Brennen und Reizung der Nase, Rachenentzündung (Nasenspray)","Kopfschmerzen","Mundsoor (Pilzbefall im Mund) und Heiserkeit (Inhalation)"],"sehrSelten":["Haarbalgentzündung (Follikulitis) und Brennen der Haut (Creme, Salbe)"],"unbekannt":["Hautverdünnung (Atrophie), Dehnungsstreifen, Pigmentverlust, vermehrte Behaarung, akneartige Hautentzündung (äusserliche Anwendung)","Kontaktdermatitis, Juckreiz und Schmerzen an der Auftragsstelle","Hautinfektionen, Furunkel","Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem, Verkrampfung der Atemwege","Erhöhter Augeninnendruck, Glaukom, Katarakt, verschwommenes Sehen","Perforation der Nasenscheidewand, Geschmacks- und Geruchsstörungen (Nasenspray)","Bei hoher oder langer Anwendung: Unterdrückung der Nebennieren, Wachstumsverzögerung bei Kindern"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; auf der Haut kleinflächig und kurz. Nasenspray und Inhalation führen nur zu geringen Mengen im Blut und können bei klarer Notwendigkeit angewendet werden.","stillzeit":"Nach ärztlicher Abwägung möglich; Creme oder Salbe nicht auf die Brust auftragen.","hinweise":["Creme und Salbe nicht ohne ärztliche Anweisung im Gesicht, in Hautfalten oder unter luftdichten Verbänden anwenden; Behandlung möglichst kurz halten.","Nasenspray regelmässig anwenden: die volle Wirkung kann einige Tage dauern; zur Vorbeugung schon vor Beginn der Pollensaison starten.","Nach dem Inhalieren den Mund ausspülen, um Mundsoor und Heiserkeit vorzubeugen.","Bei Kindern unter Langzeitbehandlung mit Nasenspray oder Inhalation die Körpergrösse regelmässig messen."],"darreichung":["Creme","Salbe","Lösung und Emulsion zur Anwendung auf der Haut","Nasenspray","Pulver zur Inhalation (Kombi)"]},"moenchspfeffer":{"wirkmechanismus":"Lindert Beschwerden, die in den Tagen vor der Monatsblutung auftreten. Inhaltsstoffe des Mönchspfeffer-Extrakts (u. a. Diterpene) binden an Dopamin-D2-Rezeptoren der Hirnanhangdrüse und dämpfen so eine vermehrte Ausschüttung von Prolaktin, die mit Brustspannen und anderen prämenstruellen Beschwerden in Verbindung gebracht wird. Daneben werden Wirkungen an Opioid- und Östrogenrezeptoren diskutiert; der genaue Wirkmechanismus ist nicht vollständig geklärt.","nebenwirkungen":{"unbekannt":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Schwere allergische Reaktionen mit Gesichtsschwellung, Atemnot oder Schluckbeschwerden","Kopfschmerzen, Schwindel","Magen-Darm-Beschwerden (Übelkeit, Bauchschmerzen)","Akne","Veränderungen der Monatsblutung (Zyklusstörungen)"]},"schwangerschaft":"Nicht anwenden; es liegen keine ausreichenden Daten vor. Bei Verdacht auf Schwangerschaft absetzen.","stillzeit":"Nicht anwenden – Mönchspfeffer kann die Milchbildung vermindern, und Daten zum Übergang in die Muttermilch fehlen.","hinweise":["Die Wirkung setzt allmählich ein; die Einnahme erfolgt in der Regel über mindestens 3 Monatszyklen ohne Pause.","Bei Verdacht auf Schwangerschaft absetzen.","Bei starken oder anhaltenden Beschwerden ärztlich abklären lassen (z. B. Prolaktinerhöhung oder Hypophysenerkrankung)."],"darreichung":["Filmtabletten"]},"montelukast":{"wirkmechanismus":"Hemmt Botenstoffe, die bei Asthma die Bronchien verengen und entzünden. Montelukast blockiert selektiv den Cysteinyl-Leukotrien-Rezeptor CysLT1 in den Atemwegen. Dadurch werden die Wirkungen der Leukotriene LTC4, LTD4 und LTE4 wie Bronchienverengung, Schleimbildung, Schleimhautschwellung und Einwanderung eosinophiler Entzündungszellen verhindert. Es wirkt vorbeugend, nicht als Notfallmittel.","nebenwirkungen":{"sehrHaeufig":["Infekte der oberen Atemwege"],"haeufig":["Durchfall, Übelkeit, Erbrechen","Hautausschlag","Fieber","Erhöhte Leberwerte (ALT, AST)"],"gelegentlich":["Abnorme Träume und Albträume, Schlaflosigkeit, Schlafwandeln","Angst, Unruhe, Reizbarkeit, Aggressivität, Depression, Zittern","Schwindel, Schläfrigkeit, Kribbeln oder Taubheitsgefühle, Krampfanfälle","Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie","Nasenbluten, Mundtrockenheit, Verdauungsbeschwerden","Blutergüsse, Nesselsucht, Juckreiz","Gelenk- und Muskelschmerzen, Muskelkrämpfe","Bettnässen bei Kindern, Müdigkeit, Unwohlsein, Wassereinlagerungen"],"selten":["Aufmerksamkeits- und Gedächtnisstörungen, Tics","Herzklopfen","Erhöhte Blutungsneigung","Angioödem"],"sehrSelten":["Halluzinationen, Desorientierung, Suizidgedanken und suizidales Verhalten, Zwangssymptome, Stottern","Eosinophile Granulomatose mit Polyangiitis (Churg-Strauss-Syndrom), Lungeneosinophilie","Hepatitis (Leberentzündung)","Erythema nodosum, Erythema multiforme","Thrombozytopenie (Mangel an Blutplättchen)"]},"schwangerschaft":"Daten aus Schwangerschaftsregistern zeigen kein erhöhtes Fehlbildungsrisiko; nur anwenden, wenn es klar notwendig ist.","stillzeit":"Nicht bekannt, ob Montelukast beim Menschen in die Muttermilch übergeht (im Tierversuch ja); nur anwenden, wenn klar notwendig.","hinweise":["Einmal täglich einnehmen, bei Asthma am Abend; auch bei Beschwerdefreiheit weiter einnehmen. Beim akuten Anfall das Notfallspray verwenden.","Bei Stimmungsveränderungen, Albträumen, Unruhe, Depression oder Suizidgedanken – auch bei Kindern – sofort ärztlich melden.","Inhalatives Kortison nicht eigenmächtig durch Montelukast ersetzen oder absetzen."],"darreichung":["Filmtabletten","Kautabletten","Granulat"]},"morphin":{"wirkmechanismus":"Lindert starke Schmerzen, indem es an die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark bindet. Morphin ist ein Agonist vor allem am μ-Opioidrezeptor und hemmt die Weiterleitung und Wahrnehmung von Schmerzreizen; es wirkt zudem beruhigend, hustendämpfend und hemmt die Darmbewegung. In der Leber entstehen das ebenfalls wirksame Morphin-6-glucuronid und Morphin-3-glucuronid, die über die Niere ausgeschieden werden und sich bei Niereninsuffizienz anreichern.","nebenwirkungen":{"sehrHaeufig":["Obstipation (Verstopfung)","Übelkeit"],"haeufig":["Schläfrigkeit, Schwindel, Kopfschmerzen","Verwirrtheit, Schlaflosigkeit","Appetitlosigkeit","Erbrechen, Bauchschmerzen, Mundtrockenheit","Schwitzen, Hautausschlag, Juckreiz","Schwäche, Müdigkeit"],"gelegentlich":["Atemdepression (abgeschwächte Atmung)","Halluzinationen, Unruhe, Euphorie","Krampfanfälle, Ohnmacht","Blutdruckabfall, Herzklopfen","Ileus (Darmlähmung)","Harnverhalt","Überempfindlichkeitsreaktionen, Nesselsucht","Lungenödem"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Abhängigkeit, Toleranz und Entzugssymptome","Hyperalgesie (erhöhte Schmerzempfindlichkeit)","Miosis (enge Pupillen)","Gallenkoliken, Verschlechterung einer Pankreatitis","Verminderte Libido, Erektionsstörung, Ausbleiben der Regel","Bronchospasmus"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Längere Anwendung kann beim Neugeborenen ein Entzugssyndrom auslösen; unter der Geburt Gefahr einer Atemdepression beim Kind.","stillzeit":"Morphin geht in die Muttermilch über und kann beim Säugling Atemdepression und Schläfrigkeit verursachen. Stillen wird nicht empfohlen.","hinweise":["Retardtabletten und -kapseln ganz schlucken, nicht zerkauen oder zerkleinern – sonst Gefahr einer lebensbedrohlichen Überdosierung.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Gegen Verstopfung von Beginn an vorbeugen (Abführmittel, ausreichend trinken).","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome)."],"darreichung":["Retardtabletten","Retardkapseln","Tabletten","Lösung zum Einnehmen","Injektionslösung"]},"mosunetuzumab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit bösartigen B-Zellen, damit diese zerstört werden. Mosunetuzumab ist ein bispezifischer IgG1-Antikörper gegen CD20 auf B-Zellen und CD3 auf T-Zellen. Die Bindung aktiviert die T-Zellen, die Zytokine und zytotoxische Proteine freisetzen und die CD20-tragenden Zellen abtöten. Auch gesunde B-Zellen werden über längere Zeit vermindert.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom (Fieber, Schüttelfrost, Blutdruckabfall)","Neutropenie, Anämie, Thrombozytopenie","Infektionen der oberen Atemwege","Hypophosphatämie (Phosphatmangel)","Kopfschmerzen","Hautausschlag, Juckreiz","Fieber, Müdigkeit","Durchfall"],"haeufig":["Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Lungenentzündung","Tumor-Flare (schmerzhafte Lymphknotenschwellung)","Hypokaliämie, Hypomagnesiämie (Kalium-, Magnesiummangel)","Erhöhte Leberwerte"],"unbekannt":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom)","Tumorlysesyndrom","Progressive multifokale Leukenzephalopathie (PML, seltene Hirninfektion)"]},"schwangerschaft":"Kann beim Ungeborenen die B-Zellen vermindern; in der Schwangerschaft nicht empfohlen. Frauen verhüten während und mindestens 3 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Die ersten Infusionen werden mit Überwachung gegeben; Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Infektzeichen umgehend ärztlich abklären lassen.","Patientenkarte immer mitführen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"moxifloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es das Kopieren ihrer Erbsubstanz verhindert. Moxifloxacin hemmt die bakteriellen Topoisomerasen II (DNA-Gyrase) und IV; es entstehen tödliche DNA-Brüche. Es wirkt gut gegen Pneumokokken, atypische Erreger (Mykoplasmen, Chlamydien, Legionellen) und viele Anaerobier, aber kaum gegen Pseudomonas. Moxifloxacin verlängert die QT-Zeit deutlicher als andere Fluorchinolone und wird hauptsächlich über die Leber ausgeschieden.","nebenwirkungen":{"haeufig":["Pilzinfektionen","Kopfschmerzen, Schwindel","QT-Verlängerung bei niedrigem Kalium","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Erhöhte Leberwerte","Reaktionen an der Infusionsstelle","Bei Augentropfen: Augenschmerzen und -reizung, Geschmacksstörung"],"gelegentlich":["Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie), verlängerte Gerinnungszeit","Allergische Reaktionen, Hautausschlag, Juckreiz, Nesselsucht","Unruhe, Angst, Schlafstörungen, Zittern, Kribbeln, Geschmacksstörungen, Verwirrtheit","Sehstörungen, verschwommenes Sehen","QT-Verlängerung, Herzklopfen, Herzrasen, Vorhofflimmern, Angina pectoris","Atemnot, Appetitlosigkeit, Verstopfung, Verdauungsbeschwerden","Gelenk- und Muskelschmerzen, Schwitzen"],"selten":["Anaphylaxie, Angioödem","Krampfanfälle, periphere Neuropathie, Halluzinationen, Depression","Tinnitus, Hörstörungen bis Taubheit","Ventrikuläre Herzrhythmusstörungen, Ohnmacht, Blutdruckschwankungen","Antibiotika-assoziierte Kolitis","Gelbsucht, Hepatitis (meist cholestatisch)","Sehnenentzündung, Muskelkrämpfe, Muskelschwäche","Nierenfunktionsstörung bis Nierenversagen; Hyperglykämie (Überzuckerung)"],"sehrSelten":["Torsade de pointes, Herzstillstand","Fulminante Hepatitis bis Leberversagen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Sehnenriss, Verschlechterung einer Myasthenia gravis","Agranulozytose, Panzytopenie","Psychotische Reaktionen mit Selbstgefährdung","Hypoglykämie (Unterzuckerung)"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Hyponatriämie (SIADH), hypoglykämisches Koma","DRESS und akute generalisierte exanthematische Pustulose","Aortenaneurysma und -dissektion, Herzklappenundichtigkeit"]},"schwangerschaft":"Tabletten und Infusion sind kontraindiziert (Gelenkknorpelschäden im Tierversuch). Augentropfen nur nach ärztlicher Abwägung.","stillzeit":"Tabletten und Infusion sind kontraindiziert. Augentropfen nach ärztlicher Abwägung vertretbar.","hinweise":["Vor Beginn alle anderen Medikamente angeben: viele Mittel verlängern zusätzlich die QT-Zeit.","Bei Herzklopfen, Ohnmacht, Sehnenschmerzen, Kribbeln, Gelbsucht oder plötzlichen Brust-, Bauch- oder Rückenschmerzen sofort ärztliche Hilfe holen.","Abstand zu Mineralstoff-, Eisen- und Multivitaminpräparaten sowie Antazida einhalten; starke Sonne meiden."],"darreichung":["Filmtabletten","Infusionslösung","Augentropfen"]},"moxonidin":{"wirkmechanismus":"Senkt den Blutdruck, indem es im Hirnstamm die Signale des sympathischen Nervensystems an Herz und Gefässe vermindert. Moxonidin bindet bevorzugt an Imidazolin-I1-Rezeptoren in der rostralen ventrolateralen Medulla und senkt so den Sympathikustonus und den Gefässwiderstand. Da es Alpha-2-Rezeptoren deutlich schwächer anspricht als Clonidin, verursacht es seltener Müdigkeit und Mundtrockenheit. Herzfrequenz und Herzleistung bleiben weitgehend unverändert.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Kopfschmerzen","Schwindel, Drehschwindel","Schläfrigkeit","Schlaflosigkeit","Übelkeit, Erbrechen, Durchfall, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Rückenschmerzen","Schwäche"],"gelegentlich":["Nervosität","Ohnmacht (Synkope)","Ohrensausen (Tinnitus)","Bradykardie (verlangsamter Herzschlag)","Blutdruckabfall, auch beim Aufstehen","Angioödem (Schwellung von Gesicht und Rachen)","Nackenschmerzen","Ödeme (Wassereinlagerungen)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; es gibt kaum Erfahrungen bei Schwangeren.","stillzeit":"Geht in die Muttermilch über; soll in der Stillzeit nicht angewendet werden, sonst abstillen.","hinweise":["Nicht abrupt absetzen, sondern über etwa zwei Wochen ausschleichen.","Alkohol meiden; Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen.","Blutdruck regelmässig kontrollieren."],"darreichung":["Filmtabletten"]},"mpox-pocken-impfstoff":{"wirkmechanismus":"Bringt dem Immunsystem bei, Pocken- und Mpox-Viren zu erkennen. Der Impfstoff enthält ein stark abgeschwächtes Vacciniavirus (Modifiziertes Vacciniavirus Ankara, MVA-BN), das sich in menschlichen Zellen nicht mehr vermehren kann. Es löst eine Antikörper- und zelluläre Immunantwort aus, die wegen der engen Verwandtschaft der Orthopockenviren auch vor Mpox und Pocken schützt. Weil sich das Impfvirus nicht vermehrt, kann der Impfstoff auch bei geschwächtem Immunsystem eingesetzt werden.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung, Verhärtung und Juckreiz an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Müdigkeit","Übelkeit"],"haeufig":["Fieber, Schüttelfrost","Gelenk- und Gliederschmerzen","Appetitlosigkeit","Knötchen, Verfärbung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Infekte der oberen Atemwege","Lymphknotenschwellung","Schwindel, Kribbeln (Parästhesien)","Schlafstörungen","Durchfall, Erbrechen","Hautausschlag"],"selten":["Nesselsucht (Urtikaria)","Herzrasen (Tachykardie)","Bindehautentzündung"]},"schwangerschaft":"Nur wenige Daten, Tierstudien unauffällig. Anwendung nur, wenn der mögliche Nutzen (z. B. nach Kontakt) das Risiko überwiegt.","stillzeit":"Unbekannt, ob der Impfstoff in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Zwei Dosen unter die Haut im Abstand von mindestens 28 Tagen; nach früherer Pockenimpfung genügt je nach Situation eine Dosis.","Nach Kontakt mit einer an Mpox erkrankten Person möglichst innerhalb von 4 Tagen impfen.","Der volle Schutz besteht erst etwa 2 Wochen nach der zweiten Dosis; Schutzmassnahmen bleiben wichtig."],"darreichung":["Injektionssuspension"]},"mucopolysaccharidpolysulfat":{"wirkmechanismus":"Fördert die Rückbildung von Blutergüssen und Schwellungen. Mucopolysaccharidpolysulfat ist ein heparinähnlicher Stoff (Heparinoid), der in die Haut eindringt, dort die Blutgerinnung örtlich hemmt, die Auflösung von Fibrin fördert und entzündungshemmend wirkt. Zudem unterstützt es die Regeneration des Bindegewebes.","nebenwirkungen":{"unbekannt":["Hautrötung, Juckreiz oder Brennen an der Auftragsstelle","Allergische Hautreaktionen (Kontaktekzem)"]},"schwangerschaft":"Bisher keine Hinweise auf Risiken; systematische Studien fehlen. Nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Nach Rücksprache anwendbar; nicht im Brustbereich auftragen.","hinweise":["Mehrmals täglich dünn auftragen und leicht einreiben; bei schmerzhaften Venenentzündungen nur auftragen, nicht massieren.","Nicht auf offene Wunden, Schleimhäute oder in die Augen bringen.","Bei starker Schwellung, Rötung und Schmerzen im Bein an eine tiefe Thrombose denken und ärztlich abklären."],"darreichung":["Creme","Gel"]},"multivitamine-kombination":{"wirkmechanismus":"Ergänzt Vitamine und Mineralstoffe, die der Körper für Stoffwechsel, Blutbildung, Nerven, Abwehr und Knochen braucht. Die Bestandteile wirken wie die entsprechenden Nährstoffe aus der Nahrung: B-Vitamine als Coenzyme im Energiestoffwechsel, Vitamin C und E als Antioxidanzien, Vitamin D und Calcium im Knochenstoffwechsel, Folsäure bei Zellteilung und Blutbildung (Vorbeugung von Neuralrohrdefekten beim Ungeborenen), Eisen, Zink und Magnesium als Bestandteile von Enzymen und Blutfarbstoff. Zusammensetzung und Dosierung unterscheiden sich je nach Präparat deutlich. Ein Nutzen ist vor allem bei tatsächlichem Mangel oder erhöhtem Bedarf belegt.","nebenwirkungen":{"sehrSelten":["Allergische Reaktionen (Hautausschlag, Juckreiz) bis hin zur Anaphylaxie"],"unbekannt":["Magen-Darm-Beschwerden wie Übelkeit, Bauchschmerzen, Verstopfung oder Durchfall","Harmlose Gelbfärbung des Urins (Vitamin B2)","Dunkel gefärbter Stuhl bei eisenhaltigen Präparaten"]},"schwangerschaft":"Speziell für Schwangere zusammengesetzte Präparate (mit Folsäure, Jod und meist Eisen) sind geeignet und empfohlen; Präparate mit hohem Vitamin-A-Gehalt meiden.","stillzeit":"In üblicher Dosierung erlaubt; Stillpräparate decken den Mehrbedarf.","hinweise":["Kein Ersatz für eine ausgewogene Ernährung; nicht mehrere Vitamin- oder Mineralstoffpräparate gleichzeitig einnehmen.","Mineralstoffhaltige Präparate zeitversetzt zu Antibiotika (Tetracycline, Chinolone), Schilddrüsenhormonen und Bisphosphonaten einnehmen.","Bei Kinderwunsch Folsäure mindestens 4 Wochen vor der Empfängnis beginnen (Vorbeugung von Neuralrohrdefekten).","Eisenhaltige Präparate kindersicher aufbewahren."],"darreichung":["Filmtabletten","Brausetabletten","Kapseln"]},"multivitamine-parenteral":{"wirkmechanismus":"Ersetzt die Vitamine, die bei ausschliesslicher Ernährung über die Vene nicht mit der Nahrung aufgenommen werden. Die Präparate enthalten wasserlösliche Vitamine (B-Vitamine, Vitamin C, Biotin, Folsäure; z. B. Soluvit N), fettlösliche Vitamine (A, D, E, K; Vitalipid N) oder eine Mischung (Cernevit, ohne Vitamin K). Die Vitamine wirken als Coenzyme und Antioxidantien im Energie-, Eiweiss- und Fettstoffwechsel, bei der Blutbildung, der Blutgerinnung (Vitamin K) und im Knochenstoffwechsel (Vitamin D).","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie (besonders auf Vitamin B1)","Hautausschlag, Hautrötung, Juckreiz","Reaktionen an der Infusionsstelle (Brennen, Venenreizung)","Übelkeit, Erbrechen","Erhöhte Leberwerte","Vitamin-A- oder -D-Überdosierung bei Langzeitanwendung oder Niereninsuffizienz"]},"schwangerschaft":"Zur Deckung des normalen Vitaminbedarfs bei künstlicher Ernährung anwendbar; eine Überdosierung, besonders von Vitamin A, muss vermieden werden.","stillzeit":"Anwendung möglich; die Vitamine gehen in die Muttermilch über, eine Überdosierung ist zu vermeiden.","hinweise":["Wird im Spital oder bei der Heimernährung einer Infusionslösung bzw. Fettemulsion zugesetzt; die fertige Mischung vor Licht schützen.","Bei längerer Anwendung werden Vitaminstatus und Leberwerte kontrolliert, besonders bei Leber- oder Nierenkrankheit."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung","Emulsion als Zusatz zu Fettemulsionen"]},"mupirocin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien und tötet sie in höherer Konzentration ab. Mupirocin blockiert das bakterielle Enzym Isoleucyl-tRNA-Synthetase und unterbricht so die Eiweissherstellung der Bakterien. Es wirkt vor allem gegen Staphylokokken, auch Methicillin-resistente (MRSA), und Streptokokken. Wegen seines besonderen Wirkmechanismus gibt es keine Kreuzresistenz mit anderen Antibiotika.","nebenwirkungen":{"haeufig":["Brennen an der Auftragsstelle"],"gelegentlich":["Juckreiz, Rötung, Stechen und Trockenheit an der Auftragsstelle","Allergische Hautreaktionen (Kontaktdermatitis)","Reizungen der Nasenschleimhaut (Nasensalbe)"],"sehrSelten":["Allgemeine allergische Reaktionen wie Anaphylaxie, Ausschlag am ganzen Körper, Nesselsucht, Angioödem"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Erfahrungen sind begrenzt, es gelangt aber kaum Wirkstoff in den Körper.","stillzeit":"Anwendung möglich; wird eine wunde Brustwarze behandelt, die Stelle vor dem Stillen gründlich abwaschen.","hinweise":["Nicht länger als 10 Tage anwenden; bessert sich die Infektion nach 3–5 Tagen nicht, ärztlich kontrollieren lassen.","Nicht mit anderen Salben oder Cremes auf derselben Stelle mischen – die Wirkung wird verdünnt.","Nicht in die Augen bringen; die Hautsalbe ist nicht für die Nase bestimmt (dafür gibt es die Nasensalbe)."],"darreichung":["Salbe","Nasensalbe"]},"mycophenolat-mofetil":{"wirkmechanismus":"Bremst die Vermehrung von Abwehrzellen, die das transplantierte Organ angreifen würden. Mycophenolat-Mofetil ist ein Prodrug und wird im Körper zur Mycophenolsäure umgewandelt. Diese hemmt das Enzym Inosinmonophosphat-Dehydrogenase und damit die Neubildung von Guanin-Nukleotiden. T- und B-Lymphozyten sind auf diesen Weg angewiesen, weshalb ihre Vermehrung und die Antikörperbildung gezielt gehemmt werden.","nebenwirkungen":{"sehrHaeufig":["Infektionen inkl. Sepsis (z. B. Herpes, Gürtelrose, Zytomegalie, Candida im Verdauungstrakt)","Leukopenie (Mangel an weissen Blutkörperchen), Thrombozytopenie, Anämie","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen"],"haeufig":["Lungenentzündung, Grippe, Harnwegsinfekte","Hautkrebs (nicht-melanozytär) und gutartige Hautwucherungen","Magen-Darm-Blutungen, Kolitis (Darmentzündung), Magenschleimhautentzündung","Erhöhte Leberwerte, Hepatitis","Blutdruckveränderungen, Ödeme","Stoffwechselveränderungen (erhöhter Blutzucker, Kalium- und Magnesiummangel, erhöhte Blutfette)","Kopfschmerzen, Zittern, Krampfanfälle, Schlaflosigkeit, Depression","Akne, Haarausfall"],"gelegentlich":["Lymphome und andere bösartige Lymphwucherungen","Magen-Darm-Durchbruch (Perforation)"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","BK-Virus-Nephropathie (Nierenschaden durch Virus)","Erythroblastopenie (Pure Red Cell Aplasia)","Hypogammaglobulinämie (Antikörpermangel), Bronchiektasen","Interstitielle Lungenerkrankung"]},"schwangerschaft":"Kontraindiziert: Mycophenolat verursacht häufig Fehlbildungen (Ohren, Gesicht, Herz) und Fehlgeburten. Vor Therapiebeginn zwei negative Schwangerschaftstests; Frauen verhüten während und bis 6 Wochen nach der Behandlung zuverlässig.","stillzeit":"Kontraindiziert; nicht stillen.","hinweise":["Strikt nach Plan einnehmen und nie eigenmächtig absetzen (Abstossungsgefahr).","Blutbild in den ersten Monaten regelmässig kontrollieren lassen; Fieber, Halsschmerzen oder blaue Flecken sofort melden.","Konsequenter Sonnenschutz und regelmässige Hautkontrollen.","Kapseln und Tabletten nicht öffnen oder zerkleinern; Kontakt mit dem Pulver vermeiden (Schwangere)."],"darreichung":["Kapseln","Filmtabletten","Pulver zur Herstellung einer Suspension","Pulver für Infusionslösung"]},"mycophenolsaeure":{"wirkmechanismus":"Dämpft das Immunsystem, indem es die Vermehrung von Abwehrzellen bremst. Mycophenolsäure hemmt reversibel das Enzym Inosinmonophosphat-Dehydrogenase (IMPDH) und damit die Neubildung von Guanosin-Nukleotiden. T- und B-Lymphozyten sind besonders auf diesen Syntheseweg angewiesen und werden daher stärker gehemmt als andere Zellen. Mycophenolat-Mofetil wird im Körper in denselben Wirkstoff umgewandelt.","nebenwirkungen":{"sehrHaeufig":["Virale, bakterielle und Pilzinfektionen","Leukopenie (Mangel an weissen Blutkörperchen)","Durchfall"],"haeufig":["Atemwegsinfektionen, Lungenentzündung","Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen)","Kopfschmerzen, Schwindel","Bauchschmerzen, Übelkeit, Erbrechen, Verstopfung, Blähungen, Verdauungsbeschwerden","Erhöhte Leberwerte","Husten, Atemnot","Bluthochdruck","Müdigkeit, Fieber, Wassereinlagerungen, Gelenkschmerzen"],"gelegentlich":["Hautkrebs (Basaliom, Spinaliom), Lymphome und andere lymphoproliferative Erkrankungen","Sepsis, Wundinfektionen","Neutropenie, Lymphopenie","Pankreatitis (Bauchspeicheldrüsenentzündung), Magen-Darm-Geschwüre"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","BK-Virus-Nephropathie","Erythroblastopenie (Ausfall der roten Blutbildung)","Hypogammaglobulinämie (Antikörpermangel), Bronchiektasen","Interstitielle Lungenerkrankung"]},"schwangerschaft":"Kontraindiziert: stark fruchtschädigend (Fehlbildungen, Fehlgeburten). Vor Beginn Schwangerschaftstests; Frauen müssen während und bis 6 Wochen nach der Behandlung zuverlässig verhüten, Männer bis 90 Tage danach Kondome verwenden.","stillzeit":"Kontraindiziert.","hinweise":["Tabletten unzerkaut, nicht zerbrochen und regelmässig zur gleichen Zeit einnehmen.","Nicht ohne ärztliche Anweisung mit Mycophenolat-Mofetil austauschen – die Dosierungen sind nicht gleichwertig.","Sonnenschutz und regelmässige Haut- und Blutbildkontrollen; Fieber, Halsschmerzen oder blaue Flecken sofort melden.","Während und bis 6 Wochen nach der Behandlung kein Blut spenden; Männer bis 90 Tage danach keinen Samen spenden."],"darreichung":["Magensaftresistente Filmtabletten"]}});
